import {StrictMode,useEffect,useMemo,useRef,useState,type ComponentType,type MouseEvent as ReactMouseEvent,type ReactNode} from "react";
import {createRoot} from "react-dom/client";
import {Alert,ApplicationShell,ArticleCard,ArticleCardGrid,IconButton,Footer,FooterBottom,FooterBrand,FooterColumn,FooterContact,FooterGrid,FooterSocial,SiteNavigation,Badge,Breadcrumbs,Button,Card,CardContent,CardHeader,CardTitle,CaseCard,CaseCardGrid,ChartContainer,Checkbox,CodeBlock,ComparisonTable,CopyChip,CtaBanner,DashboardPage,DataList,DashboardPanel,DataManagementPage,Dialog,DropdownMenu,Faq,FeatureCard,FeatureGrid,FileTree,FilterBar,FormField,Input,KpiCard,KpiGrid,LinkCells,LogoStrip,Map as LocatorMap,MegaActions,MegaCascade,MegaColumns,MegaFeature,MegaGrid,MegaTabs,PageState,Pagination,PricingTable,ProfileCard,Progress,Prose,Radio,RadioGroup,Range,Frame,FrameGrid,RectTitle,SearchBar,SideTabs,SplitButton,FilamentButton,Switch,TableOfContents,Table,TableBody,TableCell,TableContainer,TableHead,TableHeader,TableRow,Tabs,Textarea,ThemeToggle,Timeline,ToastProvider,Tooltip,splitRectTitle,useToast} from "@mithtech-bengaluru/tonaldepth-react";
import "@mithtech-bengaluru/tonaldepth-react/styles.css";
import "./styles.css";
import "./selectors.css";
import generatedProps from "./props.generated.json";
import coreTokens from "@mithtech-bengaluru/tonaldepth-core/tokens.json";
// The loader's own source. tokens.json says what a family is *called*;
// this says what is actually fetched, and it is the only place the weight
// axis and the available styles are written down.
import fontsSource from "../../../tokens/source/fonts.json";
// The library's icon set — TD first, Phosphor for the rest. Every role is
// imported because the Icons page previews all of them, not a sample.
import { AcceptIcon, AddIcon, ArrowOutIcon, ArrowRightIcon, BellIcon, CallIcon, CancelIcon, ChatCircleIcon, CheckboxMarkIcon, ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon, CloseIcon, CopyIcon, CubeIcon, DateIcon, DatasetIcon, DeleteIcon, DotIcon, DownloadIcon, EditIcon, EmailIcon, EnvelopeSimpleIcon, ErrorIcon, FacebookIcon, FileIcon, FolderIcon, GearIcon, InfoIcon, InstagramIcon, InteractiveIcon, LinkedInIcon, ListIcon, MoonIcon, PhoneIcon, ReadTimeIcon, SearchIcon, SquaresFourIcon, SuccessIcon, SunIcon, WarningIcon, WhatsAppIcon, XIcon, YouTubeIcon, LAMP_WEIGHT, TD_ICON_ROLES } from "@mithtech-bengaluru/tonaldepth-react";

/* The editorial half of an entry, and the half a generator cannot write.
   `options` expands the choice props the generated table can only name —
   `ButtonVariant` is a type, not an answer — and `notes` carries the contracts
   a three-column props table has no room for: what the component does NOT do,
   what the caller still owes it, and which prop wins when two disagree. */
type DocOption=[prop:string,values:string,note:ReactNode];
type Doc={id:string;name:string;group:"Actions"|"Forms"|"Feedback"|"Overlays"|"Navigation"|"Mega menus"|"Surfaces & data"|"App patterns"|"Marketing";summary:string;code:string;preview:ReactNode;options?:DocOption[];notes?:ReactNode[]};

/* Props tables are generated from packages/react/src by tooling/docs/props.mjs.
   They were retyped by hand until 2026-08-27, and had drifted: Button's variant
   default was documented as "primary" when the component ships "secondary". */
const PROPS: Record<string, string[][]> = generatedProps;
function DialogDemo(){const[open,setOpen]=useState(false);return <><Button onClick={()=>setOpen(true)}>Open dialog</Button><Dialog open={open} onOpenChange={setOpen} title="Delete project" description="This action cannot be undone." footer={<><Button variant="ghost" onClick={()=>setOpen(false)}>Cancel</Button><Button variant="destructive" onClick={()=>setOpen(false)}>Delete</Button></>}><p>All history and comments will be permanently removed.</p></Dialog></>}
function DropdownDemo(){const[value,setValue]=useState("standard");return <DropdownMenu label={value} value={value} onValueChange={setValue} items={[{value:"standard",label:"Standard"},{value:"express",label:"Express"},{value:"overnight",label:"Overnight",disabled:true}]}/>}
function ToastDemo(){const{toast}=useToast();return <div className="row"><Button variant="outline" onClick={()=>toast({title:"Saved",description:"Your changes are safe."})}>Info</Button><Button variant="outline" onClick={()=>toast({title:"Deployed",variant:"success"})}>Success</Button><Button variant="outline" onClick={()=>toast({title:"Failed",description:"Please retry.",variant:"error"})}>Error</Button></div>}
const LAMP_ICON=<CubeIcon weight={LAMP_WEIGHT} />;
const ICON_DEMO=<ListIcon weight={LAMP_WEIGHT} />;

/* ── Theming reference ────────────────────────────────────────────────
   Values are read from the package's own generated tokens.json, so this
   section cannot drift from what ships. Only the role sentences are
   editorial, because "what this font is for" is a decision, not data. */
const tokenBy=(cssVar:string)=>Object.values(coreTokens).find(t=>t.$extensions.tonaldepth.cssVariable===cssVar);
const light=(cssVar:string)=>tokenBy(cssVar)?.$value??"—";
const dark=(cssVar:string)=>{const t=tokenBy(cssVar);return t?.$extensions.tonaldepth.modes?.dark??t?.$value??"—";};
const FONT_ROLES:[string,string][]=[
 ["--td-font-display","Display headings (h1–h3) and rectangle titles"],
 ["--td-font-sans","Body copy"],
 ["--td-font-ui","UI text: buttons, labels, nav, h4–h6"],
 ["--td-font-mono","Counts, timestamps, command-palette hints"],
];
const CORE_COLOURS=["--td-bg","--td-surface","--td-surface-2","--td-ink","--td-ink-2","--td-ink-3","--td-brand","--td-brand-text","--td-accent","--td-accent-text","--td-green","--td-green-text","--td-error","--td-error-text"];
const SERIES_COLOURS=Array.from({length:8},(_,i)=>`--td-series-${i+1}`);
const familyName=(cssVar:string)=>light(cssVar).split(",")[0].replace(/"/g,"").trim();
function Swatch({cssVar}:{cssVar:string}){return <div className="swatch"><span className="swatch-chip" style={{background:`var(${cssVar})`}}/><code>{cssVar}</code><span className="swatch-val">{light(cssVar)}</span>{dark(cssVar)!==light(cssVar)?<span className="swatch-val swatch-val--dark">dark {dark(cssVar)}</span>:null}</div>;}
/* ── The font tester ─────────────────────────────────────────────────
   Four specimens of "Ag" say which face is which; they do not say whether a
   headline fits, whether the rupee sign is drawn, or what the numerals do at
   14px. Type the real string and read it in every family at once.

   Families, weight axes and styles come from `tokens/source/fonts.json` —
   the file the @font-face block is generated from — so a family added there
   appears here without this page being edited. */
const FONT_TEST_SIZES=[44,28,18,14];
/* `"400"` is a single weight; `"200 900"` is a variable axis. */
const weightAxis=(weight:string):[number,number]=>{const stops=weight.split(/\s+/).map(Number);return[stops[0],stops[stops.length-1]]};
const FONT_TEST_DEFAULT="Order to cash, cut to four days — ₹12,40,500";
function FontTester(){
  const[text,setText]=useState(FONT_TEST_DEFAULT);
  const[weight,setWeight]=useState(400);
  const[italic,setItalic]=useState(false);
  const sample=text||FONT_TEST_DEFAULT;
  return <div className="playground fonttest">
    <div className="playground-controls">
      <label className="pg-field"><span>Test text</span>
        <input value={text} onChange={e=>setText(e.target.value)} placeholder="Type anything"/></label>
      <label className="pg-field"><span>Weight <b>{weight}</b></span>
        <input type="range" min={100} max={900} step={100} value={weight} onChange={e=>setWeight(Number(e.target.value))}/></label>
      <label className="pg-check"><input type="checkbox" checked={italic} onChange={e=>setItalic(e.target.checked)}/>
        <span>Italic</span></label>
    </div>
    {fontsSource.families.map(family=>{
      const[min,max]=weightAxis(family.weight);
      const applied=Math.min(max,Math.max(min,weight));
      const hasItalic=family.styles.includes("italic");
      const clamped=applied!==weight;
      const flattened=italic&&!hasItalic;
      return <div className="fonttest-family" key={family.token}>
        <div className="fonttest-head">
          <strong style={{fontFamily:`var(${family.token})`}}>{family.family}</strong>
          <code>{family.token}</code>
          <span>{family.role}</span>
          <span className="fonttest-axis">{family.variable?`variable ${min}–${max}`:`one weight · ${min}`} · {family.styles.join(" + ")} · {family.package}</span>
        </div>
        {clamped||flattened?<p className="hint fonttest-note">
          {clamped?<>Clamped to <b>{applied}</b>. {family.family} ships {min===max?`a single weight`:`${min}–${max}`}, and asking for one it does not have leaves the browser to smear the outlines. </>:null}
          {flattened?<>No italic face — a synthesised slant is not this family, so the sample stays upright.</>:null}
        </p>:null}
        <div className="fonttest-lines">{FONT_TEST_SIZES.map(size=><div className="fonttest-line" key={size}>
          <span className="fonttest-size">{size}</span>
          <span className="fonttest-text" style={{fontFamily:`var(${family.token})`,fontWeight:applied,fontStyle:italic&&hasItalic?"italic":"normal",fontSize:size}}>{sample}</span>
        </div>)}</div>
      </div>;
    })}
    <p className="hint">Every sample resolves the live <code>--td-font-*</code> variable, so what you are reading is the stack a component would get — fallback included. If a face has not loaded, this is where it shows.</p>
  </div>;
}
const FONTS_JSON_SAMPLE=`{
  "family": "Hanken Grotesk",
  "token": "--td-font-ui",
  "package": "@fontsource-variable/hanken-grotesk@5",
  "slug": "hanken-grotesk",
  "variable": true,
  "weight": "100 900",
  "styles": ["normal", "italic"],
  "subsets": ["latin", "latin-ext"]
}`;
const TOKENS_JSON_SAMPLE=`{
  "path": "color.brand",
  "$type": "color",
  "$value": "#FF5E29",
  "$extensions": {
    "tonaldepth": {
      "cssVariable": "--td-brand",
      "modes": { "dark": "#FF5E29" }
    }
  }
}`;
/* Preview glyphs. Filled, because a lamp needs a solid mask to glow from —
   an outline has almost no alpha for drop-shadow to bloom. */
const IGrid=()=><SquaresFourIcon weight={LAMP_WEIGHT} />;
const IGear=()=><GearIcon weight={LAMP_WEIGHT} />;
const IBell=()=><BellIcon weight={LAMP_WEIGHT} />;
const ICube=()=><CubeIcon weight={LAMP_WEIGHT} />;
const IList=()=><ListIcon weight={LAMP_WEIGHT} />;
const IChat=()=><ChatCircleIcon weight={LAMP_WEIGHT} />;
/* The WhatsApp channel gets the WhatsApp mark. A generic chat bubble does not
   name a channel, which is the whole job of a channel icon ([[L23]]). */
const IWhatsApp=()=><WhatsAppIcon weight={LAMP_WEIGHT} />;
const IPhone=()=><PhoneIcon weight={LAMP_WEIGHT} />;
const IMail=()=><EnvelopeSimpleIcon weight={LAMP_WEIGHT} />;
const docs:Doc[]=[
 {id:"icon-button",name:"IconButton",group:"Actions",summary:"The lamp. The housing takes the depth ladder; the icon carries the state — unlit at rest, lit on hover, brighter on press — and the label, when there is one, never rides that ramp. Round and 42px when icon-only; a labelled one is a CTA, so it is a pill at the large control height with a glyph scaled to match the label.",code:`import { IconButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Icon-only needs a name — there is no text node to read. */}\n<IconButton icon={<PlayIcon />} aria-label="Play" />\n\n{/* Labelled: the icon glows, the label holds its ink. */}\n<IconButton icon={<WhatsAppIcon />} label="Message us" tone="whatsapp-quiet" />\n\n{/* Social links render as anchors. */}\n<IconButton icon={<LinkedInIcon />} href="/linkedin" aria-label="LinkedIn" tone="linkedin" />`,options:[["tone",`"neutral" | "papaya" | "azure" | "invert"`,<>The surface and filled housings. <code>neutral</code> is the surface button and its lamp lights green; the other three are filled housings, where the lamp lights white because papaya on papaya is invisible.</>],["tone",`"whatsapp" | "facebook" | "instagram" | "x" | "linkedin" | "youtube"`,<>The filled channel tones \u2014 each carries its platform's own colour as the housing's fill. Reach for one when the button <em>is</em> the call to action.</>],["tone",`"whatsapp-quiet" | "facebook-quiet" | "instagram-quiet" | "x-quiet" | "linkedin-quiet" | "youtube-quiet"`,<>The quiet form of each channel: a carved surface housing whose lamp lights that platform's colour. This is the one for a <strong>row</strong> of channels \u2014 a footer's social links, a contact strip \u2014 because six filled discs is a wall of fills, while six quiet ones read as one material with six different lights in it.</>],["label",`ReactNode`,<>Absent leaves it round and 42px. Present turns it into a pill at the large control height with the glyph scaled to the label — a labelled icon button is a CTA, not an affordance.</>],["href",`string`,<>Renders an anchor instead of a button. Anchor attributes such as <code>target</code> and <code>rel</code> pass through with it.</>],["glow",`string`,<>Any CSS colour, overriding the tone's lamp. It is mixed at the <code>--td-glow-*</code> strengths, so a custom colour still rides the same rest / hover / press ladder.</>],],notes:[<><strong>An icon-only button needs a name.</strong> With no <code>label</code>, pass <code>aria-label</code> or <code>aria-labelledby</code> — there is no text node for a screen reader to read. The component logs a warning when neither is there.</>,<><strong>The icon has to be filled.</strong> Pass a library glyph at <code>LAMP_WEIGHT</code>. A glow traces the alpha edge of what it lights, so an outline mark glows as a hollow outline and reads as a smudge.</>,<><strong>Only the icon moves.</strong> The housing takes the depth ladder and the label holds its ink in every state. If you find yourself recolouring the label on hover, the component is being used against its grain.</>,<>Everything else is the native element — <code>disabled</code>, <code>onClick</code>, <code>type</code>, <code>title</code> and the rest pass straight through to the button or the anchor.</>,],preview:<div style={{display:"flex",flexDirection:"column",gap:20}}><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} aria-label="Play"/><IconButton icon={LAMP_ICON} aria-label="Brand action" tone="papaya"/><IconButton icon={LAMP_ICON} aria-label="Accent action" tone="azure"/><IconButton icon={LAMP_ICON} aria-label="Inverted action" tone="invert"/><IconButton icon={LAMP_ICON} aria-label="Disabled" disabled/></div><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} label="Message us" tone="whatsapp-quiet"/><IconButton icon={LAMP_ICON} label="Book a call" tone="papaya"/><IconButton icon={LAMP_ICON} label="Read the brief"/></div><div className="row" style={{gap:12,flexWrap:"wrap",alignItems:"center"}}><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="WhatsApp" tone="whatsapp"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="LinkedIn" tone="linkedin"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="Facebook" tone="facebook"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="Instagram" tone="instagram"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="X" tone="x"/><IconButton icon={LAMP_ICON} href="#icon-button" aria-label="YouTube" tone="youtube"/></div><p className="hint" style={{margin:0}}>Hover and press each one — only the icon's colour and glow move. The label never does.</p></div>},
 {id:"site-navigation",name:"SiteNavigation",group:"Navigation",summary:"The public site header, and the one mith.tech runs in production. Brand, a row of links and mega-menu triggers, and an actions slot. Sticky, retracting on the way down and returning on the way up, flush when stuck. Each panel is one fixed size its content fills rather than a size its content drives.",code:`import { SiteNavigation } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SiteNavigation\n  brand={<a href="/">Mithtech</a>}\n  actions={<Button size="sm">Talk to us</Button>}\n  items={[\n    { kind: "link", label: "Pricing", href: "/pricing" },\n    {\n      kind: "menu",\n      id: "services",\n      label: "Services",\n      title: "What we run",\n      description: "Implementation, integration and managed operations.",\n      content: <ServicesPanel />,\n    },\n  ]}\n/>`,options:[["items[].kind",`"link" | "menu"`,<>A <code>link</code> is a flat anchor in the bar. A <code>menu</code> is a mega-panel trigger and carries <code>id</code>, <code>title</code>, an optional <code>description</code>, <code>cta</code> and <code>footer</code>, and the <code>content</code> that fills the sheet.</>],["retract",`boolean · default true`,<>Retract on the way down, return on the way up. Off pins the bar in place.</>],["revealFloor",`number · default 140`,<>The scroll depth below which the bar is always present, whichever way the page is moving. Keeps the header from flickering at the top of a page.</>],],notes:[<><strong>This is the header the marketing site actually ships.</strong> mith.tech’s <code>Navbar</code> is this component with site copy poured into it \u2014 the sticking, the retract, the <code>--nav-offset</code> publishing and the fixed panel size all live here rather than in the site. Panel <em>content</em> stays with the site, because the library has no business holding a list of the industries someone sells into.</>,<><strong>Not <a href="#desktop-navigation">DesktopNavigation</a>.</strong> That one is the bar inside a signed-in product: a flat row of links, no panels, no scroll behaviour, no router seam. This one is for a public page. They look alike at a glance because a header is a header; what separates them is that only this one has panels, sticky retract and <code>renderLink</code>.</>,<><strong>A panel is one fixed size its content fills</strong> — not a size its content drives. Two triggers beside each other must not open two differently shaped sheets, so write the content to the panel rather than sizing the panel to the content.</>,<><strong>Hand your router the anchor.</strong> A <code>link</code> item takes <code>renderLink</code>, which is given the class and the href and returns the element — Next's <code>Link</code>, React Router's <code>Link</code>. Without it every internal link is a document load. The navigation keeps ownership of the class and the aria state.</>,<>A menu's <code>cta</code> takes the element rather than a href for the same reason: you supply the anchor, so the router owns it.</>,<><code>actions</code> is the slot for the theme toggle and the primary call to action. <code>children</code> render between the bar and the panels — that is where a mobile drawer goes.</>,<><code>label</code> names the navigation landmark and <code>closeLabel</code> names each panel's close button. Both are screen-reader text, so translate them with the rest of the page.</>,],preview:<div style={{position:"relative",minHeight:180}}><SiteNavigation retract={false} brand={<a href="#site-navigation" style={{fontFamily:"var(--td-font-display)",fontSize:22,letterSpacing:"0.02em"}}>MITHTECH</a>} actions={<><ThemeToggle/><Button variant="primary" size="sm">Talk to us</Button></>} items={[{kind:"link",label:"Pricing",href:"#site-navigation"},{kind:"link",label:"Work",href:"#site-navigation",current:true},{kind:"menu",id:"services",label:"Services",title:"What we run",description:"Implementation, integration and managed operations \u2014 on open source, with the source in your hands.",cta:<a className="td-mega-cta" href="#site-navigation">All services</a>,footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="ERPNext" href="#site-navigation" points={["Discovery to go-live","Data migration"]}>The full rollout, run by the people who stay.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Medusa" href="#site-navigation" points={["Headless catalogue","Payments and tax"]}>Commerce, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="n8n" href="#site-navigation" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard><FeatureCard tone="brand" icon={ICON_DEMO} title="Plane" href="#site-navigation" points={["GitHub sync"]}>Engineering execution without the SaaS.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Cal.com" href="#site-navigation" points={["Self-hosted booking"]}>Scheduling inside your perimeter.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="Managed ops" href="#site-navigation" points={["24×7 on-call"]}>After go-live, for as long as you want us.</FeatureCard></MegaGrid>},{kind:"menu",id:"platforms",label:"Platforms",title:"Where it runs",description:"Same stack, three grounds. The choice is compliance and cost, not capability.",footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="Hetzner" href="#site-navigation" points={["Bare metal, EU"]}>Where most of it runs.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="AWS" href="#site-navigation" points={["When compliance asks"]}>The same stack, a different bill.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="On-prem" href="#site-navigation" points={["Your rack, your rules"]}>For data that cannot leave.</FeatureCard></MegaGrid>},{kind:"menu",id:"knowledge",label:"Knowledge",title:"What we have written down",description:"Guides, comparisons and the engagements behind them.",footer:<MegaActions><a className="td-cta" href="#site-navigation">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions>,content:<MegaCascade groups={[{id:"guides",label:"Guides",icon:<ICube/>,branches:[{id:"erp",title:"ERP",hint:"Process, hosting, tuning",href:"#site-navigation",items:[{href:"#site-navigation",title:"ERPNext in 90 days"},{href:"#site-navigation",title:"Data migration from Tally"},{href:"#site-navigation",title:"Choosing your modules"}]},{id:"commerce",title:"Commerce",hint:"Storefront and checkout",items:[{href:"#site-navigation",title:"Medusa vs Shopify"},{href:"#site-navigation",title:"Gateways in India"}]}]},{id:"work",label:"Case studies",icon:<IList/>,branches:[{id:"retail",title:"Retail",hint:"What shipped, and what it cost",items:[{href:"#site-navigation",title:"Commercely replatform",detail:"Retail"},{href:"#site-navigation",title:"Rework Industries",detail:"Manufacturing"}]}]}]}/>}]}/></div>},
 {id:"footer",name:"Footer",group:"Navigation",summary:"The site footer, composed rather than configured: a brand band, link columns, a recessed contact well, a social row and a bottom bar. Each part is its own export, so a site takes the pieces it needs.",code:`import { Footer, FooterGrid, FooterBrand, FooterColumn, FooterContact, FooterBottom } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Footer>\n  <FooterGrid>\n    <FooterBrand name="Mithtech" href="/">\n      Open-source implementation for SMEs.\n    </FooterBrand>\n    <FooterColumn title="Services" links={[{ href: "/erpnext", label: "ERPNext" }]} />\n    <FooterColumn title="Company" links={[{ href: "/work", label: "Work" }]} />\n  </FooterGrid>\n\n  {/* The contact well sits BELOW the grid, not inside it — as a column\n      it squeezes an address into ~130px. */}\n  <FooterContact items={[{ key: "Email", value: "hello@mith.tech" }]} />\n\n  <FooterBottom note="© 2026 Mithtech" links={[{ href: "/privacy", label: "Privacy" }]} />\n</Footer>`,notes:[<><strong>Seven exports, taken as needed.</strong> <code>Footer</code> is the landmark; <code>FooterGrid</code> lays out the brand band and the link columns; <code>FooterBrand</code>, <code>FooterColumn</code>, <code>FooterContact</code>, <code>FooterSocial</code> and <code>FooterBottom</code> are the parts.</>,<><strong>FooterBrand</strong> takes <code>name</code>, an optional <code>href</code>, <code>renderLink</code>, and the standing description as children.</>,<><strong>FooterColumn</strong> takes <code>title</code>, <code>links</code> as a list of href and label, and <code>renderLink</code>.</>,<><strong>FooterContact</strong> takes <code>label</code> and <code>items</code>, each a <code>key</code> such as Email or Phone and a <code>value</code>. It goes <em>below</em> the grid, not inside it — as a column it squeezes an address into about 130px.</>,<><strong>FooterBottom</strong> takes the legal <code>note</code>, a <code>social</code> node, <code>links</code> and <code>renderLink</code>.</>,<><strong><code>FooterSocial</code> is the row that goes in that <code>social</code> slot.</strong> It supplies placement and nothing else: pass icon-only lamps — <a href="#icon-button">IconButton</a> with a <strong>quiet</strong> channel tone (<code>linkedin-quiet</code>, <code>instagram-quiet</code>, …) and no <code>label</code>. Quiet is the one to reach for: the housing stays the carved surface button every other icon button is, so a row of six reads as one material, and only the lamp takes the platform's colour. The filled tones (<code>linkedin</code>, <code>youtube</code>) put a solid platform-coloured disc on the page, which is a wall of fills and the one move the system forbids. Give it a <code>label</code>: that becomes the row's <code>aria-label</code>, which is the only name a screen reader has for a group of icon-only links.</>,<><strong>renderLink is the prop that matters here.</strong> A footer is where the whole link inventory lives, so this is what decides whether sixty internal links route through the framework or fall back to document loads. The footer owns the markup around the anchor; this owns the anchor.</>,<><code>label</code> on <code>Footer</code> names the contentinfo landmark.</>,],preview:<Footer><FooterGrid><FooterBrand name="Mithtech" href="#footer">Open-source implementation for SMEs — Frappe, Medusa and n8n, run by the people who will still be here in year three.</FooterBrand><FooterColumn title="Services" links={[{href:"#footer",label:"ERPNext"},{href:"#footer",label:"Commerce"},{href:"#footer",label:"Automation"}]}/><FooterColumn title="Company" links={[{href:"#footer",label:"Work"},{href:"#footer",label:"Contact"}]}/></FooterGrid><FooterContact items={[{key:"Email",value:"hello@mith.tech"},{key:"Phone",value:"+91 90087 70738"},{key:"Office",value:"Bengaluru"},{key:"Hours",value:"Mon–Fri, 09:30–18:30 IST"}]}/><FooterBottom note="© 2026 Mithtech Innovative Solutions Private Limited" social={<FooterSocial label="Mithtech on social media"><IconButton icon={<LinkedInIcon weight={LAMP_WEIGHT}/>} href="#footer" aria-label="LinkedIn" tone="linkedin-quiet"/><IconButton icon={<InstagramIcon weight={LAMP_WEIGHT}/>} href="#footer" aria-label="Instagram" tone="instagram-quiet"/><IconButton icon={<XIcon weight={LAMP_WEIGHT}/>} href="#footer" aria-label="X" tone="x-quiet"/><IconButton icon={<YouTubeIcon weight={LAMP_WEIGHT}/>} href="#footer" aria-label="YouTube" tone="youtube-quiet"/></FooterSocial>} links={[{href:"#footer",label:"Privacy"},{href:"#footer",label:"Terms"}]}/></Footer>},
 {id:"article-card",name:"ArticleCard",group:"Marketing",summary:"Blog and knowledge cards: an optional cover, a category eyebrow, a title that is the whole-card link, an excerpt, an \u201cIn this piece\u201d well holding the tools, files and datasets the piece carries, and a date + read-time meta line.",code:`import { ArticleCard, ArticleCardGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n// What the piece carries, in the order the reader should meet it. The kind\n// picks the chip's glyph and the category colour it holds; meta is the\n// machine face — a format, a size, a running state — and is set in mono.\n// Leave meta off where there is no machine value to report.\n//\n//   live         a tool that runs in the page          green\n//   download     a file the reader takes away          azure\n//   data         the numbers behind the piece, raw     violet\n//   interactive  something the reader operates         papaya\n\nconst assets = [\n  { kind: "live", label: "Cost calculator", href: "#calculator", meta: "live" },\n  { kind: "download", label: "Line-item sheet", href: "/line-items.xlsx", meta: "xlsx \u00b7 84 kb", download: true },\n  { kind: "data", label: "11-engagement dataset", href: "/engagements.csv", meta: "csv", download: true },\n  { kind: "interactive", label: "Scoping checklist", href: "#checklist" },\n];\n\n<ArticleCardGrid>\n  <ArticleCard\n    href="/blog/erpnext-implementation-cost"\n    eyebrow="Cost &amp; hosting"\n    title="What an ERPNext implementation actually costs in India"\n    excerpt="Eleven engagements, the line items that moved."\n    assets={assets}\n    assetsLabel="In this piece"\n    date="14 Jul 2026"\n    readTime="9 min"\n    author={{ name: "Manoj Bhat", initials: "MB" }}\n  />\n</ArticleCardGrid>`,options:[["assets[].kind",`"live" | "download" | "data" | "interactive"`,<>What the reader gets, which picks the chip's glyph and the category colour. <code>live</code> is a tool that runs in the page — green. <code>download</code> is a file taken away — azure. <code>data</code> is the numbers behind the piece, offered raw — violet. <code>interactive</code> is something operated rather than read — papaya.</>],["href",`string`,<>Makes the title the whole-card link and turns on the card's link affordance. Omit it and the card drops the affordance rather than pointing nowhere.</>],["assetsLabel",`ReactNode · default "In this piece"`,<>The well's heading. Rename it when the strip holds something the default sentence does not describe.</>],],notes:[<><strong>The assets well only appears when there is something in it.</strong> An empty <code>assets</code> array renders no well, which is why a draft card is a clean card rather than an empty box.</>,<><strong>The well stacks up to three rows that scroll sideways as one.</strong> The assets are split in the order you give them \u2014 six become 2+2+2, four become 2+2, two become 1+1 \u2014 so keep related items adjacent and they stay on a row together. Rows are real elements rather than a wrapping column, because a wrapping column gives every chip in a column the widest chip's width and short labels then trail a gap.</>,<>An asset's <code>meta</code> is the machine face — <code>xlsx · 84 kb</code>, <code>csv</code>, <code>live</code> — set in mono and upper-cased. Leave it off where there is no machine value to report; it is not a place for a second label.</>,<><code>download: true</code> marks that asset's anchor <code>download</code>, so the file saves instead of navigating. A <code>download</code> kind without it navigates away, which is almost never what was meant.</>,<><code>icon</code> on an asset overrides the kind's glyph, for a file whose own mark says more than its category does.</>,<><code>author</code> takes a <code>name</code> plus either <code>initials</code> for the carved monogram or a full <code>avatar</code> node.</>,<><code>cover</code>, <code>eyebrow</code>, <code>excerpt</code>, <code>date</code> and <code>readTime</code> are each optional and each disappear cleanly. <code>ArticleCardGrid</code> is the responsive grid to put the cards in.</>,],preview:<ArticleCardGrid><ArticleCard href="#article-card" eyebrow="Cost &amp; hosting" title="What an ERPNext implementation actually costs in India" excerpt="Eleven engagements, the line items that moved, and the three that never do." assets={[{kind:"live",label:"Cost calculator",href:"#article-card",meta:"live"},{kind:"live",label:"Hosting benchmarks",href:"#article-card",meta:"live"},{kind:"download",label:"Line-item sheet",href:"#article-card",meta:"xlsx \u00b7 84 kb",download:true},{kind:"download",label:"Quote template",href:"#article-card",download:true},{kind:"data",label:"11-engagement dataset",href:"#article-card",meta:"csv",download:true},{kind:"interactive",label:"Scoping checklist",href:"#article-card"}]} date="14 Jul 2026" readTime="9 min" author={{name:"Manoj Bhat",initials:"MB"}}/><ArticleCard href="#article-card" eyebrow="Migration" title="Leaving Shopify without taking the shop down" excerpt="A catalogue cutover that ran in parallel for six weeks, and what it cost to keep both live." assets={[{kind:"interactive",label:"Cutover timeline",href:"#article-card",meta:"interactive"},{kind:"download",label:"Runbook",href:"#article-card",meta:"pdf \u00b7 1.2 mb",download:true}]} date="02 Jun 2026" readTime="12 min" author={{name:"S. Rao",initials:"SR"}}/><ArticleCard eyebrow="Draft" title="What an unlisted-share ledger owes its holders" excerpt="No link and nothing to carry — the card drops both the whole-card affordance and the well rather than showing an empty one." date="—" readTime="—"/></ArticleCardGrid>},
 {id:"case-card",name:"CaseCard",group:"Marketing",summary:"A case study reduced to its outcome — eyebrow, headline, summary, and outcome metrics in the machine face.",code:`import { CaseCard, CaseCardGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CaseCardGrid>\n  <CaseCard\n    href="/case-studies/rework"\n    eyebrow="Manufacturing"\n    title="Order-to-cash cut to four days"\n    summary="Nine plants onto one ERPNext instance."\n    metrics={[{ label: "Order-to-cash", value: "-38%" }]}\n  />\n</CaseCardGrid>`,options:[["href",`string`,<>Makes the title the whole-card link and renders the call to action. Without it the card drops the CTA rather than pointing nowhere.</>],["cta",`ReactNode · default "Read the case study"`,<>The words on that link. Only rendered when <code>href</code> is set.</>],],notes:[<><strong>Metrics are the machine face.</strong> Each is a <code>label</code> and a <code>value</code>, and the value is set in mono because it is a measured number. Two or three is the useful range — a case card is an outcome, not a report.</>,<><code>visual</code> is the slot for a logo or a plate; <code>eyebrow</code> is the sector or the category, and <code>summary</code> is the one paragraph.</>,<><code>CaseCardGrid</code> is the responsive grid. Cards in it stretch to a common height, so keep the summaries within a line of each other.</>,],preview:<CaseCardGrid><CaseCard href="#case-card" eyebrow="Manufacturing" title="Order-to-cash cut to four days" summary="Nine plants moved off spreadsheets and a legacy AX install onto one ERPNext instance." metrics={[{label:"Order-to-cash",value:"-38%"},{label:"Plants live",value:"9"},{label:"Go-live",value:"11 wks"}]}/><CaseCard eyebrow="Logistics" title="Despatch without the phone calls" summary="No link on this one — the card drops its call to action rather than pointing nowhere." metrics={[{label:"Manual touches",value:"-71%"}]}/></CaseCardGrid>},
 {id:"feature-card",name:"FeatureCard",group:"Marketing",summary:"The reused shape for a capability, a service, or a platform. Tone moves the icon lamp, never a fill.",code:`import { FeatureCard, FeatureGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FeatureGrid columns={3}>\n  <FeatureCard tone="brand" title="ERPNext implementation" points={["Discovery to go-live"]}>\n    Run by the people who will still be here in year three.\n  </FeatureCard>\n</FeatureGrid>`,options:[["tone",`"neutral" | "brand" | "accent" | "green"`,<>Moves the icon lamp and nothing else — never a fill, never a tinted card. Tone is category, so use it to separate kinds of capability, not to rank them.</>],["href",`string`,<>Makes the title the whole-card link.</>],["FeatureGrid columns",`2 | 3 | 4`,<>How many the grid aims for at desktop width. It still reflows below that, so this is a ceiling rather than a fixed count.</>],],notes:[<><code>icon</code> takes a filled glyph — it is a lamp, and an outline cannot read as lit.</>,<><code>points</code> is a list of short capability lines, rendered as the card's own list. <code>children</code> is the body paragraph and <code>footer</code> a standing fact under it — “Included in every retainer”.</>,<><code>eyebrow</code> is the category above the title. It is small caps, so keep it to a word or two.</>,<>The card is the reused shape for a capability, a service or a platform. If it needs a metric it is a <a href="#case-card">CaseCard</a>; if it needs a cover and a date it is an <a href="#article-card">ArticleCard</a>.</>,<><strong>The services grid is this card, and there is deliberately no second card shape for it.</strong> The design system’s <code>10-marketing/services</code> tile is an icon, a title and a line of text in a two-column grid — which is <code>FeatureCard</code> with <code>icon</code>, <code>title</code> and <code>children</code> inside <code>FeatureGrid columns={2}</code>, and nothing else. Building a narrower card for it would have given the library two shapes to keep in step for one job. Its tile also washes the icon in 18% brand; here the tone moves the lamp instead.</>,],preview:<FeatureGrid columns={3}><FeatureCard tone="brand" icon={ICON_DEMO} eyebrow="ERP" title="ERPNext implementation" href="#feature-card" points={["Discovery to go-live","Data migration"]}>The full stack of an ERP rollout.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} eyebrow="Commerce" title="Medusa storefronts" href="#feature-card" points={["Headless catalogue","Payments and tax"]}>One product record, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} eyebrow="Automation" title="n8n workflows" footer="Included in every retainer" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard></FeatureGrid>},
 {id:"comparison-table",name:"ComparisonTable",group:"Marketing",summary:"Criteria down, options across. The argued-for column takes the ladder's selected step, never a coloured band.",code:`import { ComparisonTable } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ComparisonTable\n  caption="Open source against proprietary SaaS"\n  columns={[{ key: "oss", label: "Open source", highlight: true }, { key: "saas", label: "SaaS" }]}\n  rows={[{ label: "Source access", cells: { oss: true, saas: false } }]}\n/>`,options:[["columns[].highlight",`boolean`,<>Marks the column the page is arguing for. It renders as the selected step of the depth ladder — a pressed well with papaya ink — never a coloured band.</>],["captionHidden",`boolean · default false`,<>Keeps the caption for screen readers but takes it off the page, for a table that already sits under a heading saying the same thing.</>],["criteriaLabel",`ReactNode · default "Criterion"`,<>The header of the first column, the one holding the row labels.</>],["yesLabel / noLabel",`string · default "Yes" / "No"`,<>The accessible text behind the yes and no marks. The marks themselves are drawn, so this is what a screen reader reads.</>],],notes:[<><strong>Cells are keyed by the column's <code>key</code>.</strong> A row's <code>cells</code> is a record, not an array, so the columns can be reordered without touching a single row.</>,<><code>true</code> and <code>false</code> render as the yes and no marks. Any other node renders as itself — a price, a duration, a sentence. A key that is missing or <code>undefined</code> renders an em dash, which is how you say “not applicable” rather than “no”.</>,<>Both a column and a row take an optional <code>note</code>: the small second line under the label, for the qualifier that would otherwise bloat the cell.</>,<><code>caption</code> is required. A comparison with no stated question is an argument the reader has to reconstruct.</>,],preview:<ComparisonTable caption="Open source implementation against proprietary SaaS" criteriaLabel="What you are buying" columns={[{key:"oss",label:"Open source",note:"Mithtech",highlight:true},{key:"saas",label:"Proprietary SaaS"},{key:"custom",label:"Bespoke build"}]} rows={[{label:"Source access",cells:{oss:true,saas:false,custom:true}},{label:"Per-seat licence",note:"Charged annually, per named user",cells:{oss:"None",saas:"₹2,400",custom:"None"}},{label:"Time to first go-live",cells:{oss:"8-14 weeks",saas:"2-6 weeks",custom:"6-18 months"}},{label:"Exit path",cells:{oss:"Your database, your schema",saas:false,custom:undefined}}]}/>},
 {id:"cta-banner",name:"CtaBanner",group:"Marketing",summary:"The closing ask. It carries weight through depth and scale rather than a brand fill.",code:`import { Button, CtaBanner } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CtaBanner\n  eyebrow="Next step"\n  title="Talk to a principal consultant"\n  description="Thirty minutes, no deck."\n  actions={<Button size="lg">Book a call</Button>}\n  assurance="Reply within one business hour, IST."\n/>`,options:[["align",`"split" | "center" · default "split"`,<><code>split</code> sets the copy against the actions across the banner — the page-end ask that still has something to say. <code>center</code> stacks everything on the axis, for a short closing line with one button.</>],],notes:[<><strong>Pass your own Buttons to <code>actions</code>.</strong> The banner supplies placement, not button styling — which is what lets one banner carry a primary and a ghost without inventing a third button variant.</>,<><code>assurance</code> is the reassurance under the actions: the reply time, the no-obligation line, the standing fact. It is smaller and quieter than the description on purpose.</>,<><code>eyebrow</code> and <code>description</code> are optional; <code>title</code> is not.</>,<>The banner carries its weight through depth and scale, never a brand fill. If it is not loud enough, the page above it is competing with it.</>,],preview:<CtaBanner eyebrow="Next step" title="Talk to a principal consultant" description="Thirty minutes, no deck. Bring the process that is hurting and we will tell you whether we are the right people for it." actions={<><Button size="lg">Book a call</Button><Button variant="ghost" size="lg">Send a message</Button></>} assurance="Reply within one business hour, IST."/>},
 {id:"timeline",name:"Timeline",group:"Marketing",summary:"Phases, process, roadmaps. State reads from the dot's depth and the current phase is announced in text. One axis prop turns it from a timeline into a roadmap: the same rail, the same dot, the same three states, measured on planning periods instead of elapsed time.",code:`import { Timeline } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The timeline: time is a stamp against now, so it trails the row. */}\n<Timeline\n  label="Implementation phases"\n  items={[\n    { title: "Discovery", time: "Week 1-2", state: "done" },\n    { title: "Build", time: "Week 3-6", state: "current" },\n  ]}\n/>\n\n{/* The roadmap: time is the window the item belongs to, so it leads it. */}\n<Timeline\n  axis="period"\n  label="Platform roadmap"\n  items={[\n    { title: "Stripe + Razorpay", time: "Q1 2026", state: "done" },\n    { title: "Self-hosted Plane", time: "Q2 2026", state: "current" },\n  ]}\n/>`,options:[["axis",`"elapsed" · default`,<><code>time</code> is a stamp against now — “2 weeks ago”, “week 8” — so it trails the row the way every machine value in this system does.</>],["axis",`"period"`,<><strong>The roadmap form.</strong> <code>time</code> is the planning window the item belongs to — “Q4 2025”, “H1 2027” — so it leads the item as its heading, in papaya mono, because the period is what the reader scans down.</>],["items[].state",`"done" | "current" | "upcoming" · default "upcoming"`,<>Read from the dot's depth. <code>current</code> also prints <code>currentLabel</code> as visible text and <code>done</code> announces <code>doneLabel</code> to a screen reader, so the state is never carried by colour alone.</>],["currentLabel",`string · default "Current phase"`,<>The visible marker on the current item.</>],["doneLabel",`string · default "Complete"`,<>The screen-reader-only text on a completed item.</>],],notes:[<>An item takes <code>title</code>, an optional <code>time</code>, <code>meta</code> and <code>description</code>. <code>time</code> is a machine-reported value — a date, a duration, a week number — and is set in mono; prose belongs in <code>meta</code>.</>,<><code>label</code> names the sequence for a screen reader. The component renders an ordered list, so the reading order is the phase order.</>,<>Nothing enforces one <code>current</code>. Two of them is a roadmap with two live phases, which is sometimes true and usually a mistake.</>,<><strong>There is no separate Roadmap component, and that is the decision rather than an omission.</strong> A roadmap is this component measured on a different axis — same rail, same dot, same three states, same anatomy — so it is <code>axis="period"</code>. Building a second component would have given the design system two things to correct every time the dot changed.</>,<><strong><code>time</code> means something different on each axis, and only one of them is rendered.</strong> On <code>elapsed</code> it trails the row; on <code>period</code> it leads the item. There is no way to show both, because an item has one position on one axis.</>,<>The design system's roadmap pulses its live dot on an infinite animation. That is not reproduced: state here is depth and a named light, and a component that never stops moving is the one thing a reader cannot stop reading.</>,],preview:<div style={{display:"grid",gap:32}}><Timeline label="Implementation phases" items={[{title:"Discovery",time:"Week 1-2",meta:"Two workshops",description:"Process mapping with the people who actually run the process.",state:"done"},{title:"Data migration",time:"Week 7-9",meta:"Two dry runs",description:"Masters first, then open transactions, then a rehearsal cutover.",state:"current"},{title:"Go-live",time:"Week 10",description:"Floor support for the first full cycle."}]}/><Timeline axis="period" label="Platform roadmap" items={[{title:"Discovery and the Commercely foundation",time:"Q4 2025",description:"Scoped the engagement and shipped the first version on Hetzner.",state:"done"},{title:"Stripe and Razorpay",time:"Q1 2026",description:"Live payments on both gateways, with reconciliation and an audit log.",state:"done"},{title:"Self-hosted Plane migration",time:"Q2 2026",description:"Atlassian exit, GitHub sync, custom modules, on-call rotation.",state:"current"},{title:"Cal.com and Twenty CRM",time:"Q3 2026",description:"Self-hosted booking, customer records inside the perimeter."}]}/></div>},
 {id:"theme-toggle",name:"ThemeToggle",group:"Actions",summary:"The system's theme switch \u2014 a round icon button whose sun and moon are lamps, or a pill that names the mode it will switch to. Same button, same behaviour, either shape.",code:`import { ThemeToggle } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Round, icon only. */}\n<ThemeToggle />\n\n{/* A pill that names the mode the press switches TO. */}\n<ThemeToggle showLabel />\n<ThemeToggle showLabel labelText={{ light: "Light", dark: "Dark" }} />`,options:[["showLabel",`boolean · default false`,<>Off is the round icon button. On turns it into a pill with visible text beside the icon — the accessible name still comes from <code>labels</code>, so the pill can stay short.</>],["storageKey",`string | null · default "td-theme"`,<>Where the choice is remembered in <code>localStorage</code>. <code>null</code> keeps it for the session only.</>],["labels",`Record<Theme, string>`,<>The accessible name, keyed by the theme the press will switch <em>to</em>. Defaults to “Switch to light theme” / “Switch to dark theme”.</>],["labelText",`Record<Theme, string>`,<>The visible pill text, keyed the same way. Defaults to “Light mode” / “Dark mode”.</>],],notes:[<><strong>Both label props are keyed by the destination, not the current state.</strong> When the page is dark, the button reads the <code>light</code> entry, because that is what pressing it does.</>,<><strong>The theme lives on the document.</strong> The button stamps <code>data-theme</code> on the root element and mirrors it to storage; it does not hold the theme itself. That is what lets a whole page follow one attribute.</>,<>It watches that attribute, so two toggles on one page stay in step and an app that changes the theme from its own settings screen is picked up without a reload.</>,<>Until it mounts there is no attribute to read, so it renders unpressed and corrects itself in an effect rather than guessing during render and mismatching on hydration.</>,<>Blocked site data — a private window, a browser set to refuse storage — is caught rather than thrown. The toggle still works; the choice just does not survive the tab.</>,<><code>onThemeChange</code> fires with the new theme, for an app that has to persist it somewhere of its own.</>,],preview:<div className="row" style={{gap:14,flexWrap:"wrap",alignItems:"center"}}><ThemeToggle/><ThemeToggle showLabel/><ThemeToggle showLabel labelText={{light:"Light",dark:"Dark"}}/></div>},
 {id:"prose",name:"Prose",group:"Marketing",summary:"Long-form body copy. Styles authored HTML rather than needing a component per element.",code:`import { Prose } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Prose framed>\n  <h2>What an implementation covers</h2>\n  <p>An implementation is not an installation.</p>\n</Prose>`,options:[["size",`"sm" | "md" | "lg" · default "md"`,<>The measure and the type scale of the body copy. <code>lg</code> is the article body; <code>sm</code> is a note or a sidebar.</>],["framed",`boolean · default false`,<>Sets the prose on its own raised panel instead of directly on the page surface.</>],],notes:[<><strong>It styles authored HTML rather than needing a component per element.</strong> Headings h2 to h4, paragraphs, <code>ul</code> / <code>ol</code> / <code>dl</code>, blockquote with <code>cite</code>, inline <code>code</code> and <code>pre</code>, images, figure and figcaption, <code>hr</code> and tables all have rules.</>,<>Pass the markup as children, or hand a CMS body straight in — the rules attach to the elements, not to classes you have to add.</>,<>First and last child margins are collapsed, so a Prose block sits flush in whatever container it is given.</>,<>An h1 is deliberately not styled here. A page has one, and it belongs to <a href="#rect-title">RectTitle</a> or the page header, not to the body copy.</>,],preview:<Prose framed><h2>What an implementation actually covers</h2><p>An implementation is not an installation. The software is the smallest part of it: the work is deciding what your process really is, then making one system hold it.</p><ul><li>A named owner who can settle a process question.</li><li>One month of real transactions, not a sample.</li></ul><blockquote>The migration is the project. Everything else is configuration.<cite>Every ERP rollout, eventually</cite></blockquote><p>You get the <code>docker-compose.yml</code>, the migration scripts and the runbook.</p></Prose>},
 {id:"rect-title",name:"RectTitle",group:"Marketing",summary:"The headline treatment the design system is named for. It splits a line into balanced parts and scales each one until they all end at the same width, so the block reads as a rectangle. Display face, h1 to h3, with the last line landing in papaya.",code:`import { RectTitle } from "@mithtech-bengaluru/tonaldepth-react";\n\n<RectTitle text="Talk to a principal consultant." />\n\n{/* h2 and h3 run the same treatment at the ramp's smaller sizes. */}\n<RectTitle level={2} text="Order to cash, cut to four days" />\n\n{/* accent={false} keeps the whole block in default ink. */}\n<RectTitle level={3} accent={false} text="What an implementation covers" />`,options:[["level",`1 | 2 | 3 · default 1`,<>Which heading element it renders and which step of the display ramp it takes. The rect treatment runs at h1 to h3; h4 and below are the UI face and are not this component.</>],["tones[]",`"ink" | "muted" | "brand" | "accent" | "green" | "error"`,<>The ink per line, in order. These are the system's categories, not free colour — a headline that can take any hex is a headline that can break the palette.</>],["accent",`boolean · default true`,<>Lands the last line in papaya. Ignored entirely when <code>tones</code> is given.</>],["lines",`number`,<><strong>Exactly this many lines</strong>, overriding the automatic count. Reach for it when <code>maxLines</code> looks like it is being ignored: the automatic count is also held down by a words-per-line heuristic, so a five-word headline stays at two lines however high the ceiling goes. Clamped to the word count — four lines out of three words is three lines and a gap.</>],["maxLines",`number · default 3`,<>A ceiling on the split, not a target. Two lines is the floor whenever the text has at least two words.</>],["forceRectangle",`boolean · default false`,<>Squares the block off exactly, however far a line has to stretch. Off, the fitter stops at 1.5x, so a lopsided headline stays slightly ragged rather than turning a two-word line into a billboard.</>],["maxScale",`number · default 1.5`,<>The same ceiling, set by hand. Use it to loosen the fit by a measured amount instead of all the way — <code>forceRectangle</code> is this set to infinity.</>],],notes:[<><strong>The split is balanced by characters, not by words.</strong> Anton is condensed, so three words can be twice the width of three other words; balancing on word count alone produces a visibly lopsided block before the fitter ever sees it.</>,<><strong>A newline in <code>text</code> is an explicit break and beats everything.</strong> It skips the splitter, the automatic count and the two-line floor — a deliberate one-line headline is a decision rather than an accident. Use it when the break carries meaning the splitter cannot see: a name that must not be divided, a line that has to land on a verb.</>,<><strong><code>maxLines</code> is a ceiling, and the split also holds itself to roughly three words a line</strong>, so raising it past what the headline needs changes nothing — which reads as the prop being ignored. <code>lines</code> is the one that asks for a number. Watch the count in the playground above rather than assuming.</>,<>Every line is then measured and scaled up to the longest one. Only <code>font-size</code> moves — letter-spacing is never touched, because tracking a display face is how a wordmark stops being the wordmark.</>,<>If the longest line is wider than its column the whole block shrinks to fit, so the rectangle survives a narrow container instead of running off the side of the page.</>,<><code>tones</code> repeats its last entry, so a one-item list holds the whole block and a two-item list accents every line after the first. It overrides <code>accent</code> when both are set.</>,<><strong><code>splitRectTitle</code> is exported</strong> alongside the component, for when you need the same line break somewhere the component cannot render — a document title, a meta tag, a canvas. It takes the same three arguments in the same order of precedence: <code>splitRectTitle(text, maxLines, exactLines)</code>.</>,<>Fitting reads layout, so a renderer that does no layout (SSR, jsdom) gets the unfitted lines. The heading still reads correctly; it just is not squared until it reaches a browser.</>,],preview:<RectTitlePlayground/>},
 {id:"button",name:"Button",group:"Actions",summary:"Trigger actions. `primary` is the design system's own primary button \u2014 the surface housing with the small green lamp, which is grey glass at rest and lights as you reach for it. The papaya fill is `filled`, and it is the variant to reach for last. Every icon is a lamp: it alone changes across rest, hover and press, while the fill and the label hold.",code:`import { Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Button variant="primary">Save changes</Button>\n\n{/* The lamp comes with the primary variant. Drop it when the button\n    only fires an action and reports nothing. */}\n<Button variant="primary" dot={false}>Save changes</Button>\n\n{/* The papaya fill. Reserved rather than reached for. */}\n<Button variant="filled">Book the briefing</Button>\n\n{/* A leading icon becomes the lamp — it lights on hover and\n    brightens on press. The label's colour never moves. */}\n<Button leading={<BoxIcon />}>Book a call</Button>\n\n{/* Semantic fills bring their own icon. */}\n<Button variant="accept">Approve</Button>\n<Button variant="cancel">Cancel</Button>\n<Button variant="accent">Details</Button>\n\n{/* Channel buttons: surface housing, the lamp names the channel. */}\n<Button variant="call">Call us</Button>\n<Button variant="email">Email us</Button>\n<Button variant="whatsapp-quiet">WhatsApp us</Button>\n\n{/* The lowest rung — no housing at all. */}\n<Button variant="link">Read the brief</Button>\n\n{/* The small status lamp — for a control that reports a live state. */}\n<Button dot>Live feed</Button>`,options:[["variant",`"primary" \u00b7 the lamp button`,<><strong>The design system's own primary button</strong> \u2014 the surface housing carrying the small status lamp, grey glass at rest and lit green as the button is reached for. It carries the lamp <em>by default</em>, because every example the system ships has one; <code>dot={false}</code> drops it.</>],["variant",`"secondary" \u00b7 default`,<>The same surface housing without the lamp. The one most buttons should be: it fires an action and reports nothing.</>],["variant",`"filled"`,<><strong>The papaya fill.</strong> Reserved rather than reached for \u2014 filling with the brand colour is the one move the system forbids everywhere else, and a page with two of these has none. One per screen, at most.</>],["variant",`"outline" | "ghost" | "link"`,<>The quieter rungs. <code>link</code> is the lowest and has no housing at all.</>],["variant",`"destructive" | "accept" | "cancel" | "accent"`,<>The semantic fills, where the housing's colour carries the meaning. Each brings its own default icon, so <code>variant="accept"</code> is complete on its own.</>],["variant",`"whatsapp" | "whatsapp-quiet" | "call" | "email"`,<>The channel buttons, where the lamp names the channel. <code>whatsapp</code> is the filled housing; the other three sit on the surface and light azure or WhatsApp green.</>],["size",`"sm" | "md" | "lg" · default "md"`,<>The control height. <code>lg</code> is the page-level call to action; <code>sm</code> belongs in a toolbar or a table row.</>],["loading",`boolean · default false`,<>Swaps the lamp for a spinner, replaces the children with <code>loadingLabel</code>, sets <code>aria-busy</code> and disables the button.</>],["dot",`boolean · default true on "primary"`,<>The small status lamp \u2014 a 7px disc before the label, grey glass at rest and lit on hover and press. On by default for <code>primary</code> and off everywhere else; pass it to add one to any variant that reports a live state, or <code>dot={false}</code> to take it off a primary.</>],["leading / trailing",`ReactNode`,<><code>leading</code> is the lamp and carries the state. <code>trailing</code> is a directional mark — a chevron, an arrow — and is deliberately not a lamp.</>],["glow",`string`,<>Any CSS colour, overriding the variant's lamp colour. Mixed at the <code>--td-glow-*</code> strengths, so it still rides the same ladder and still follows the theme.</>],],notes:[<><strong><code>primary</code> is the surface housing with the lamp, not a fill.</strong> The design system draws exactly one primary button — <code>.td-primary</code>, a carved surface with a 7px lamp that is grey glass at rest and lights green as you reach for it — and every example it ships carries that lamp. The library used to give the name <code>primary</code> to the solid papaya fill, which is the one move the system forbids, and left the real primary button under <code>secondary</code> where nobody found it. The fill is now <code>filled</code> and the names mean what they say.</>,<><strong>Reach for <code>filled</code> last.</strong> A page with two papaya buttons has none: the fill is emphasis, and emphasis divided is emphasis spent. Depth is what separates a control from the page here — the fill is for the one action a screen exists to get.</>,<><strong>Only the icon moves.</strong> Across rest, hover and press the fill and the label hold their colour and depth alone reports the press. On a filled housing the lamp lights white, because papaya on papaya is invisible; on a surface housing it lights the channel's own colour.</>,<><strong><code>type</code> defaults to <code>"button"</code>.</strong> A Button inside a form does not submit it unless you pass <code>type="submit"</code> — which is the safe default, but it does catch people out.</>,<>The four semantic variants supply their own leading icon. Passing <code>leading</code> overrides it; passing <code>leading</code> to an emphasis variant adds one.</>,<><code>loading</code> also sets <code>disabled</code>, so there is no need to set both. Give <code>loadingLabel</code> the verb — “Saving”, not “Loading” — since it replaces the visible text.</>,<><strong>The lamp scales with the label.</strong> A leading or trailing glyph is drawn at 1.5\u00d7 the label \u2014 so it grows with <code>size</code> and you never set a glyph size yourself. Below that ratio the lamp is optically the lightest thing in the button, which is the part carrying the whole state signal. <a href="#icon-button">IconButton</a>, <a href="#split-button">SplitButton</a> and <a href="#filament-button">FilamentButton</a> share it.</>,<>Everything native passes through: <code>disabled</code>, <code>onClick</code>, <code>form</code>, <code>name</code>, <code>value</code>, <code>aria-*</code>.</>,],preview:<div style={{display:"flex",flexDirection:"column",gap:16}}><div className="row"><Button variant="primary">Primary</Button><Button variant="secondary">Secondary</Button><Button variant="filled">Filled</Button><Button variant="outline">Outline</Button><Button variant="ghost">Ghost</Button><Button variant="destructive">Delete</Button></div><p className="hint" style={{margin:0}}>The first one is the design system’s primary button: the surface housing with the small lamp. Hover it — the lamp is grey glass at rest and lights green as you reach for it, and it goes fully green while the button is held. <code>filled</code> is the papaya fill, and it is the variant to reach for last.</p><div className="row"><Button variant="accept">Accept</Button><Button variant="cancel">Cancel</Button><Button variant="accent">Details</Button><Button variant="whatsapp">WhatsApp us</Button></div><div className="row"><Button variant="whatsapp-quiet">WhatsApp us</Button><Button variant="call">Call us</Button><Button variant="email">Email us</Button><Button variant="link">Read the brief</Button></div><div className="row"><Button variant="primary">Lamp by default</Button><Button variant="primary" dot={false}>Lamp dropped</Button><Button dot>Live feed</Button><Button variant="outline" dot>Synced</Button></div><div className="row"><Button leading={LAMP_ICON}>Book a call</Button><Button variant="filled" leading={LAMP_ICON}>Save changes</Button><Button variant="outline" leading={LAMP_ICON}>Export</Button><Button leading={LAMP_ICON} loading>Saving</Button></div><p className="hint" style={{margin:0}}>Hover any of them: only the icon moves. The fill and the label are fixed in every state — depth alone reports the press. On a filled housing the lamp lights white, because papaya on papaya would be invisible; on a surface housing it lights the channel's own colour.</p></div>},
 {id:"badge",name:"Badge",group:"Feedback",summary:"Label compact state, category, or emphasis without implying an action.",code:`import { Badge } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Badge variant="success">Ready</Badge>`,options:[["variant",`"neutral" | "brand" | "success" | "accent" | "danger" · default "neutral"`,<>The category the label belongs to. <code>neutral</code> for a plain tag, <code>success</code> and <code>danger</code> for a state, <code>brand</code> and <code>accent</code> for an emphasis that is not a state.</>],],notes:[<><strong>A badge is a span, not a control.</strong> It has no press state, takes no focus and implies no action. If it is meant to be clicked it is a <a href="#button">Button</a> or a <a href="#filter-bar">FilterBar</a> chip.</>,<>Colour is category here, so pick the variant by what the label <em>means</em>, not by which colour looks right beside it.</>,<>Native span attributes pass through, including <code>title</code> and <code>aria-*</code>.</>,],preview:<div className="row"><Badge>Neutral</Badge><Badge variant="brand">Brand</Badge><Badge variant="success">Ready</Badge><Badge variant="accent">Review</Badge><Badge variant="danger">Blocked</Badge></div>},
 {id:"card",name:"Card",group:"Surfaces & data",summary:"Group related content with TonalDepth surface and depth treatments.",code:`import { Card, CardContent, CardHeader, CardTitle } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Card>\n  <CardHeader><CardTitle>Project status</CardTitle></CardHeader>\n  <CardContent>Ready for review.</CardContent>\n</Card>`,options:[["depth",`"raised" | "flat" | "inset" · default "raised"`,<><code>raised</code> is a plate offered to the reader. <code>flat</code> sits level with the page for a card that is only grouping. <code>inset</code> is cut into the surface — for something being shown rather than offered.</>],["padding",`"default" | "none" · default "default"`,<><code>none</code> gives an unpadded plate whose own children own the gutter, so a seam drawn between them runs the full width of the card instead of stopping short of the edges.</>],],notes:[<><strong>Three parts.</strong> <code>CardHeader</code> is the title row, <code>CardTitle</code> renders an h3 inside it, and <code>CardContent</code> is the body. Each is optional — a Card with plain children is a plain plate.</>,<>A header can hold more than the title: a <a href="#badge">Badge</a>, a meta line, a small action all sit in it and stay aligned.</>,<>Reach for <a href="#frame">Frame</a> instead when the card is housing something measured — a chart, a table. Chrome is raised and data is recessed, and Frame is that pairing already built.</>,],preview:<Card className="sample"><CardHeader><CardTitle>Project status</CardTitle><Badge variant="success">Ready</Badge></CardHeader><CardContent>Content stays owned by the consuming app.</CardContent></Card>},
 {id:"input",name:"Input",group:"Forms",summary:"Single-line text field with optional leading and trailing slots and an invalid state.",code:`import { Input } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Input type="email" placeholder="name@company.com" />`,options:[["invalid",`boolean · default false`,<>Marks the field failed and sets <code>aria-invalid</code>. Inside a <a href="#form-field">FormField</a> with an <code>error</code>, this is set for you.</>],["leading / trailing",`ReactNode`,<>Marks inside the field — a currency sign, a unit, a magnifier. They are marks, not controls: they take no focus and no glow.</>],["containerClassName",`string`,<>Styles the wrapper that holds the field and its slots. <code>className</code> still goes to the input itself.</>],],notes:[<><strong>Every native input attribute passes through</strong> — <code>type</code>, <code>placeholder</code>, <code>value</code>, <code>defaultValue</code>, <code>onChange</code>, <code>required</code>, <code>disabled</code>, <code>autoComplete</code>, <code>inputMode</code>. The component adds treatment, not behaviour.</>,<><strong>It has no label of its own.</strong> Wrap it in a <a href="#form-field">FormField</a> for the label, the help text and the ARIA wiring; a bare Input with only a placeholder has no accessible name.</>,<>The field is carved into the surface rather than raised: a place to put something is never lifted. That is why an Input and a <a href="#button">Button</a> of the same height read as different kinds of thing.</>,<>For a search field with suggestions, use <a href="#search-bar">SearchBar</a> — it carries the combobox pattern this does not.</>,],preview:<div className="stack"><Input type="email" placeholder="name@company.com"/><Input placeholder="Search" leading="?" /><Input placeholder="Blocked" disabled defaultValue="Read only"/></div>},
 {id:"textarea",name:"Textarea",group:"Forms",summary:"Multi-line text field matched to the Input treatment for longer form entry.",code:`import { Textarea } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Textarea placeholder="Describe the work" />`,options:[["invalid",`boolean · default false`,<>Marks the field failed and sets <code>aria-invalid</code>. Set for you when it sits in a <a href="#form-field">FormField</a> with an <code>error</code>.</>],["containerClassName",`string`,<>Styles the wrapper. <code>className</code> goes to the textarea itself.</>],],notes:[<>The same carved treatment as <a href="#input">Input</a>, at multi-line height. Native attributes pass through, <code>rows</code> among them.</>,<>Wrap it in a <a href="#form-field">FormField</a> for the label and the ARIA relationships — on its own it has no accessible name.</>,<>There is no auto-grow. A textarea that resizes as you type moves everything under it, which is worse than a scrollbar in a form.</>,],preview:<div className="stack"><Textarea placeholder="Describe the work"/><Textarea invalid defaultValue="Short" placeholder="Needs more detail"/></div>},
 {id:"form-field",name:"FormField",group:"Forms",summary:"Wire label, help text, error text, and ARIA relationships around a single child control.",code:`import { FormField, Input } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FormField label="Work email" helperText="Used only for notifications" required>\n  <Input type="email" placeholder="name@company.com" />\n</FormField>`,options:[["required",`boolean`,<>Prints the required mark beside the label and sets <code>required</code> on the child, unless the child already sets it.</>],["optional",`boolean`,<>Prints the word Optional beside the label. Purely editorial — it sets nothing on the control.</>],["error",`ReactNode`,<>The failure message. It replaces <code>helperText</code>, flips the field's invalid state, and sets <code>aria-invalid</code> on the child.</>],["helperText",`ReactNode`,<>The standing hint under the control, shown whenever there is no <code>error</code>.</>],["htmlFor",`string`,<>The control's id, when you need to own it. Left off, one is generated and given to the child.</>],],notes:[<><strong>Exactly one child element.</strong> The field clones it to attach <code>id</code>, <code>aria-describedby</code>, <code>aria-invalid</code> and <code>required</code> — so it needs a single element to clone, not a fragment and not two controls.</>,<><strong>It never overrides what the child already sets.</strong> Pass your own <code>id</code> or <code>aria-describedby</code> on the control and it survives; the field only fills gaps.</>,<><code>error</code> wins over <code>helperText</code> when both are given, so you can leave the hint in place and add the error on top of it rather than swapping them yourself.</>,<><strong>The message carries no live region.</strong> It is wired through <code>aria-describedby</code> and read when focus lands on the control. A form that validates several fields at once should announce the failures in one summary above the form — three assertive regions firing together talk over each other and the field message is announced twice.</>,],preview:<div className="stack"><FormField label="Work email" helperText="Used only for notifications" required><Input type="email" placeholder="name@company.com"/></FormField><FormField label="Summary" optional><Textarea placeholder="Describe the work"/></FormField><FormField label="Blocked" error="This field is required"><Input placeholder="Value"/></FormField></div>},
 {id:"checkbox",name:"Checkbox",group:"Forms",summary:"Toggle an independent boolean with an owned label and TonalDepth check treatment.",code:`import { Checkbox } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Checkbox label="Email notifications" defaultChecked />`,notes:[<><strong><code>label</code> is required and the component owns it</strong> — it renders the label element and the association. Do not wrap it in your own label; that gives the control two names.</>,<>Native attributes pass through: <code>checked</code>, <code>defaultChecked</code>, <code>onChange</code>, <code>disabled</code>, <code>name</code>, <code>value</code>, <code>required</code>.</>,<>For a checkbox that needs help text or an error message, put it in a <a href="#form-field">FormField</a> — the label stays here, the message comes from there.</>,<>An independent boolean is a Checkbox; one of several exclusive choices is a <a href="#radio">Radio</a>; a setting that takes effect immediately is a <a href="#switch">Switch</a>.</>,],preview:<div className="stack"><Checkbox label="Email notifications" defaultChecked/><Checkbox label="Weekly summary"/><Checkbox label="Blocked option" disabled/></div>},
 {id:"radio",name:"Radio",group:"Forms",summary:"Choose one option in a group; RadioGroup shares the underlying name and disabled state.",code:`import { Radio, RadioGroup } from "@mithtech-bengaluru/tonaldepth-react";\n\n<RadioGroup legend="Delivery" name="delivery" defaultValue="standard">\n  <Radio label="Standard" value="standard" defaultChecked />\n  <Radio label="Express" value="express" />\n</RadioGroup>`,notes:[<><strong>RadioGroup supplies the <code>name</code>.</strong> It passes it down through context, so the radios inside it belong to one group without repeating it on each. Setting <code>disabled</code> on the group disables all of them the same way.</>,<>Each <code>Radio</code> needs its own <code>value</code>. <code>label</code> is required and owned by the component, as with <a href="#checkbox">Checkbox</a>.</>,<><code>legend</code> names the group. It renders a real fieldset and legend, which is what a screen reader reads before the first option.</>,<>Selection is native — use <code>defaultChecked</code> on one radio, or <code>checked</code> with <code>onChange</code> to control it.</>,],preview:<RadioGroup legend="Delivery" name="delivery"><Radio label="Standard" value="standard" defaultChecked/><Radio label="Express" value="express"/><Radio label="Overnight" value="overnight" disabled/></RadioGroup>},
 {id:"switch",name:"Switch",group:"Forms",summary:"Toggle a setting on or off with a role=switch checkbox and owned label.",code:`import { Switch } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Switch label="Automatic updates" defaultChecked />`,notes:[<>Renders a checkbox with <code>role="switch"</code>, so it is announced as on or off rather than checked or unchecked.</>,<><code>label</code> is required and owned by the component.</>,<><strong>A switch takes effect immediately.</strong> If the change only lands when a form is submitted, that is a <a href="#checkbox">Checkbox</a>, not a switch.</>,<>Native attributes pass through: <code>checked</code>, <code>defaultChecked</code>, <code>onChange</code>, <code>disabled</code>.</>,],preview:<div className="stack"><Switch label="Automatic updates" defaultChecked/><Switch label="Beta features"/><Switch label="Locked" disabled/></div>},
 {id:"alert",name:"Alert",group:"Feedback",summary:"Communicate persistent info, success, warning, or error notices with an optional dismiss control. The category is a lamp — a lens seated in a socket carved from the panel — never a tinted band: one continuous surface, colour only where the light is.",code:`import { Alert } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Alert variant="success" title="Saved">Your changes are available.</Alert>`,options:[["variant",`"info" | "success" | "warning" | "error" · default "info"`,<>The category, carried by one lit lamp. <code>error</code> also renders with <code>role="alert"</code>; the other three take <code>role="status"</code>.</>],["onDismiss",`() => void`,<>Supplying it renders the close button. The alert does not remove itself — you own whether it is still on the page.</>],["dismissLabel",`string · default "Dismiss"`,<>The accessible name of that button.</>],],notes:[<><strong>Children must be inline content.</strong> The body is already a paragraph, so passing a <code>p</code> nests one inside another and breaks hydration. Text, links and spans are fine.</>,<><code>title</code> is required and is the sentence that has to work on its own — the lamp is the category, not the message.</>,<><strong>The category is a lamp, never a tinted band.</strong> One continuous surface with colour only where the light is; that is what keeps four alerts in a column from reading as four different materials.</>,<>For a transient message use <a href="#toast">Toast</a>. An Alert is persistent — it stays until the page or the app takes it away.</>,],preview:<div className="stack"><Alert variant="info" title="Local package">Loaded from the workspace package.</Alert><Alert variant="success" title="Verified">The React test suite passes.</Alert><Alert variant="warning" title="Registry only">GitHub Packages publishing is not yet verified.</Alert><Alert variant="error" title="Blocked">Package registry credentials are missing.</Alert></div>},
 {id:"tooltip",name:"Tooltip",group:"Feedback",summary:"Reveal contextual guidance on hover or focus around a single child element with an ARIA-linked tip.",code:`import { Tooltip, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Tooltip content="Opens guidance"><Button variant="outline">Help</Button></Tooltip>`,options:[["open",`boolean`,<>Forces the tip visible. For documentation, screenshots and tests — leave it off in an app, where hover and focus already reveal it.</>],],notes:[<><strong>Exactly one child element.</strong> It is cloned to attach <code>aria-describedby</code>, so a fragment or a bare string has nothing to attach to.</>,<>Hover and keyboard focus both reveal the tip, which is why the child should be something focusable. A tooltip on a plain span is unreachable without a mouse.</>,<>The tip is always in the DOM and hidden visually, so it is read as the control's description rather than appearing only on a pointer event.</>,<><strong>It describes, it does not name.</strong> A control whose only label is a tooltip has no accessible name — give it an <code>aria-label</code> as well.</>,],preview:<div className="row"><Tooltip content="Keyboard and pointer accessible"><Button variant="outline">Hover or focus</Button></Tooltip><Tooltip content="Persistent open state" open><Button variant="ghost">Always visible</Button></Tooltip></div>},
 {id:"forms",name:"Form controls",group:"Forms",summary:"Compose accessible labels, help, errors, text fields, and selection controls.",code:`import { FormField, Input, Checkbox } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FormField label="Work email" helperText="Used for notifications" required>\n  <Input type="email" placeholder="name@company.com" />\n</FormField>\n<Checkbox label="Email notifications" defaultChecked />`,notes:[<><strong>This page is a composition demo, not a registry item.</strong> There is nothing to install called “form controls” — it shows the parts working together.</>,<>The parts: <a href="#form-field">FormField</a> for the label, help, error and ARIA wiring; <a href="#input">Input</a> and <a href="#textarea">Textarea</a> for text; <a href="#checkbox">Checkbox</a>, <a href="#radio">Radio</a> with RadioGroup, and <a href="#switch">Switch</a> for selection.</>,<>The rule that ties them together: the control owns its own treatment, and FormField owns everything around it. Nothing here needs a form library to be accessible.</>,],preview:<div className="stack"><FormField label="Work email" helperText="Used only for notifications" required><Input type="email" placeholder="name@company.com"/></FormField><FormField label="Summary"><Textarea placeholder="Describe the work"/></FormField><Checkbox label="Email notifications" defaultChecked/><Switch label="Automatic updates" defaultChecked/></div>},
 {id:"tabs",name:"Tabs",group:"Navigation",summary:"Switch between related panels with keyboard-accessible tab semantics.",code:`import { Tabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Tabs defaultValue="overview" items={[\n  { value: "overview", label: "Overview", content: "Summary" },\n  { value: "activity", label: "Activity", content: "Recent changes" },\n]} />`,options:[["items[]",`{ value, label, content, disabled? }`,<>One object per tab. <code>content</code> is the panel, so the panels live with the tabs rather than in a separate array you have to keep in step.</>],["value / defaultValue",`string`,<>Pass <code>value</code> with <code>onValueChange</code> to control it. Pass <code>defaultValue</code> — or neither, and the first enabled tab is selected — to leave it uncontrolled.</>],["label",`string · default "Tabs"`,<>Names the tablist for a screen reader. Set it whenever there is more than one tab set on the page.</>],],notes:[<><strong>Selection follows focus.</strong> Arrow keys move between tabs and select as they go; Home and End jump to the ends. A disabled tab is skipped rather than focused and refused.</>,<>The list is a roving tabstop, so one Tab press moves into the panel rather than through every tab.</>,<>Panels are mounted one at a time. Anything expensive in a panel is not paid for until that panel is opened — and any state it holds is lost when it closes.</>,<>For a vertical rail whose selection is a lit filament rather than an underline, use <a href="#side-tabs">SideTabs</a>.</>,],preview:<Tabs defaultValue="overview" items={[{value:"overview",label:"Overview",content:"Current project status and ownership."},{value:"activity",label:"Activity",content:"Recent component-library changes."}]}/>},
 {id:"feedback",name:"Feedback",group:"Feedback",summary:"Communicate persistent alerts and contextual tooltip guidance.",code:`import { Alert, Tooltip, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Alert variant="success" title="Saved">Your changes are available.</Alert>\n<Tooltip content="Opens guidance"><Button variant="outline">Help</Button></Tooltip>`,notes:[<><strong>A composition demo, not a registry item.</strong> It shows <a href="#alert">Alert</a> and <a href="#tooltip">Tooltip</a> on one page — install those two.</>,<>The distinction worth taking from it: an Alert is persistent and page-level, a Tooltip is transient and attached to one control, and a <a href="#toast">Toast</a> is transient and app-level.</>,],preview:<div className="stack"><Alert variant="info" title="Local package">Loaded from the workspace package.</Alert><Alert variant="success" title="Verified">The React test suite passes.</Alert><Tooltip content="Keyboard and pointer accessible"><Button variant="outline">Hover or focus</Button></Tooltip></div>},
 {id:"table",name:"Table",group:"Surfaces & data",summary:"Render semantic tabular data with responsive containment.",code:`import { Table, TableBody, TableCell, TableContainer, TableHead, TableHeader, TableRow } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TableContainer><Table><TableHead><TableRow>\n  <TableHeader>Package</TableHeader><TableHeader>Status</TableHeader>\n</TableRow></TableHead><TableBody><TableRow>\n  <TableCell>React</TableCell><TableCell>Verified</TableCell>\n</TableRow></TableBody></Table></TableContainer>`,notes:[<><strong>Seven exports, one per element.</strong> <code>TableContainer</code>, <code>Table</code>, <code>TableHead</code>, <code>TableBody</code>, <code>TableRow</code>, <code>TableHeader</code> and <code>TableCell</code>. Each renders its native element with the system's treatment and nothing else.</>,<><strong><code>TableContainer</code> is the scroll container.</strong> Without it a wide table pushes the whole page sideways instead of scrolling itself — which is the one thing that goes wrong at 390px.</>,<><code>TableHeader</code> defaults to <code>scope="col"</code>. Pass <code>scope="row"</code> for a row header, as the leftmost cell of each row in a comparison.</>,<><strong>A row is pressed, not tinted.</strong> Hover sinks the row a little and the press sinks it deeper — the same grammar every row in the system uses. Nothing is required of you to get it. Mark the current row with <code>aria-selected="true"</code> (or <code>data-selected="true"</code>) and it rests recessed, the way an open nav button does.</>,<><strong>Do not set <code>border-collapse</code> on the table.</strong> The component ships the separated model with <code>border-spacing: 0</code>, which renders identically to the collapsed one here — the only borders are on the cells. It matters because a <code>&lt;tr&gt;</code> under <code>border-collapse: collapse</code> generates no box for a <code>box-shadow</code> to paint into, so the row's whole depth is discarded in silence and the highlight flattens to a tint.</>,<>There is no sorting, no pagination and no virtualisation here — this is the semantic table. For criteria against options, use <a href="#comparison-table">ComparisonTable</a>; for a table housed as data, put it in a <a href="#frame">Frame</a>.</>,<>Native attributes pass through, so <code>colSpan</code>, <code>rowSpan</code> and <code>aria-*</code> work as usual.</>,],preview:<TableContainer><Table><TableHead><TableRow><TableHeader>Package</TableHeader><TableHeader>Status</TableHeader></TableRow></TableHead><TableBody><TableRow><TableCell>React</TableCell><TableCell><Badge variant="success">Verified</Badge></TableCell></TableRow><TableRow><TableCell>Vue</TableCell><TableCell><Badge variant="accent">P0 only</Badge></TableCell></TableRow></TableBody></Table></TableContainer>},
 {id:"kpi",name:"KPI cards",group:"Surfaces & data",summary:"Present high-level metrics in a responsive token-driven grid.",code:`import { KpiCard, KpiGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n<KpiGrid>\n  <KpiCard label="Open" value="42" delta="+6" trend="up" />\n  <KpiCard label="Resolved" value="128" delta="+18%" trend="up" />\n</KpiGrid>`,options:[["trend",`"up" | "down" | "neutral" · default "neutral"`,<>Which way the <code>delta</code> reads. It colours the delta only — up is not automatically good, so the word beside it still has to say what happened.</>],["visualization",`ReactNode`,<>The slot under the value, for a sparkline or a small plot. Keep it a shape, not a chart with axes.</>],],notes:[<><code>label</code> and <code>value</code> are both required — a metric with no name is a number nobody can act on.</>,<>The value is set in the machine face. That is the point of the card: it is a measured quantity, and it should not look like prose.</>,<><code>KpiGrid</code> is the responsive grid. It reflows rather than squashing, so four cards become two rows before they become four narrow columns.</>,<><code>delta</code> is free text — “+6”, “+18%”, “2 fewer”. It is not computed for you.</>,],preview:<KpiGrid><KpiCard label="Open" value="42" delta="+6" trend="up"/><KpiCard label="Resolved" value="128" delta="+18%" trend="up"/></KpiGrid>},
 {id:"dialog",name:"Dialog",group:"Overlays",summary:"Focus-trapping modal with title, description, footer actions, Escape and outside-click dismissal.",code:`import { Dialog, Button } from "@mithtech-bengaluru/tonaldepth-react";\nimport { useState } from "react";\n\nfunction DeleteProject() {\n  const [open, setOpen] = useState(false);\n  return (\n    <>\n      <Button onClick={() => setOpen(true)}>Open dialog</Button>\n      <Dialog open={open} onOpenChange={setOpen} title="Delete project" description="This action cannot be undone."\n        footer={<><Button variant="ghost" onClick={() => setOpen(false)}>Cancel</Button><Button variant="destructive" onClick={() => setOpen(false)}>Delete</Button></>}>\n        <p>All history and comments will be permanently removed.</p>\n      </Dialog>\n    </>\n  );\n}`,options:[["open / onOpenChange",`boolean / (open) => void`,<>Both required — the dialog is controlled, always. It renders nothing at all when closed.</>],["description",`ReactNode`,<>Wired to <code>aria-describedby</code>, so it is read after the title. Prose that only matters visually belongs in the children instead.</>],["footer",`ReactNode`,<>The action row along the bottom. Pass your own Buttons; the dialog supplies the placement.</>],["closeLabel",`string · default "Close dialog"`,<>The accessible name of the corner close button.</>],],notes:[<><strong>Focus is trapped and returned.</strong> Opening moves focus to the first focusable element inside; Tab and Shift+Tab cycle within the dialog; closing returns focus to whatever had it before.</>,<><strong>Three ways out, all of them call <code>onOpenChange(false)</code>:</strong> Escape, the corner close button, and a mousedown on the backdrop. The dialog never closes itself — you own the state, so a confirm step can refuse.</>,<>It is <code>role="dialog"</code> with <code>aria-modal</code>, labelled by the title and described by the description when there is one.</>,<>Put the destructive action in the footer on the right and the cancel beside it as a ghost — that pairing is what the preview shows, and it is the one to copy.</>,],preview:<DialogDemo/>},
 {id:"dropdown-menu",name:"DropdownMenu",group:"Overlays",summary:"Single-selection menu with keyboard navigation, click-outside dismissal, and menuitemradio semantics.",code:`import { DropdownMenu } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DropdownMenu label="Standard" value="standard" onValueChange={console.log} items={[\n  { value: "standard", label: "Standard" },\n  { value: "express", label: "Express" },\n]} />`,options:[["items[]",`{ value, label, disabled? }`,<>One object per item. <code>value</code> is the key and what <code>onValueChange</code> reports.</>],["value / onValueChange",`string / (value) => void`,<>The selection is <strong>controlled</strong> — the menu holds no selection of its own. Store the value and pass it back, or nothing appears chosen.</>],["label",`ReactNode`,<>What the trigger reads. Pass the chosen item's label, which is why the demo above keeps it in the same state as <code>value</code>.</>],],notes:[<><strong>Single selection, with <code>menuitemradio</code> semantics.</strong> This is a chooser, not a list of commands — for a menu of actions, use <a href="#split-button">SplitButton</a>.</>,<>Open and closed <em>is</em> internal. Opening focuses the first enabled item; arrows wrap, Home and End jump; Escape closes and returns focus to the trigger; a mousedown outside closes it.</>,<>Choosing an item closes the menu and returns focus to the trigger, so the keyboard never lands somewhere the reader did not ask for.</>,<>A disabled item stays in the list and is skipped by the arrows, rather than disappearing — the reader can see that the option exists.</>,],preview:<DropdownDemo/>},
 {id:"toast",name:"Toast",group:"Feedback",summary:"Auto-dismissing status queue accessed through a provider and useToast hook. Carved out of the page with a 3px shade against a matching 3px highlight rather than floated on a drop shadow, and its category is the same lamp the Alert uses.",code:`import { ToastProvider, useToast, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\nfunction SaveButton() {\n  const { toast } = useToast();\n  return <Button onClick={() => toast({ title: "Saved", variant: "success" })}>Save</Button>;\n}\n\nexport function App() {\n  return <ToastProvider><SaveButton /></ToastProvider>;\n}`,options:[["toast({ variant })",`"info" | "success" | "error" · default "info"`,<>The category, carried by the same lamp the <a href="#alert">Alert</a> uses. <code>error</code> renders with <code>role="alert"</code>; the other two take <code>role="status"</code>.</>],["toast({ duration })",`number`,<>Milliseconds before it dismisses itself, overriding the provider's default for this one toast. <code>0</code> makes it stay until dismissed.</>],["ToastProvider defaultDuration",`number · default 4000`,<>The dismissal time for every toast that does not set its own.</>],],notes:[<><strong>Wrap the app once in <code>ToastProvider</code>.</strong> It renders the viewport as well as holding the queue, so there is nothing else to place on the page.</>,<><code>useToast()</code> returns <code>toast</code> and <code>dismiss</code>. <code>toast(...)</code> returns the new toast's id, which is what you hand to <code>dismiss(id)</code> to take one away early.</>,<>Called outside the provider, <code>useToast</code> throws rather than silently doing nothing — a toast that never appears is worse to debug than an error at the call site.</>,<>A toast takes a <code>title</code> and an optional <code>description</code>. Keep the title a complete sentence: it is the part that gets read.</>,<>The strip is carved out of the page with a shade against a matching highlight rather than floated on a drop shadow, which is why it reads as part of the surface at any scroll position.</>,],preview:<ToastDemo/>},
 {id:"chart-container",name:"ChartContainer",group:"Surfaces & data",summary:"A chart, housed. A Frame with the slots a plot needs already wired — the caption in the head, the legend under the well, and the well run flush because a plot carries its own margins. Renders a figure, so the plot and its caption are announced as one thing.",code:`import { ChartContainer } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ChartContainer title="Weekly signups" meta="Q3" legend={[{ label: "This week" }, { label: "Last week" }]}>\n  <svg viewBox="0 0 200 60"><polyline fill="none" stroke="currentColor" strokeWidth="2" points="0,50 40,40 80,20 120,30 160,10 200,25"/></svg>\n</ChartContainer>`,options:[["legend[]",`{ label, color? }`,<>One entry per series. <code>color</code> takes any CSS colour; left off, entries fall back to <code>--td-series-1</code> upward in order, which is the palette they should be using anyway.</>],["description",`string`,<>The chart's text alternative. It is visually hidden and wired to <code>aria-describedby</code> — so it is the only thing a screen reader gets from the plot.</>],["meta",`ReactNode`,<>The small value beside the title — a period, a unit, an as-of date.</>],],notes:[<><strong>Write the <code>description</code>.</strong> An SVG is opaque to assistive technology; without this the figure is a title and nothing else. Say what the chart shows and what the shape is, not that it is a line chart.</>,<>It renders a <code>figure</code> with a <code>figcaption</code>, so it is announced as one thing rather than a heading followed by loose graphics.</>,<><strong>You supply the SVG.</strong> There is no charting here — give the child a <code>width: 100%</code> and a <code>viewBox</code> and it scales with the card.</>,<><strong>It is a <a href="#frame">Frame</a>.</strong> A chart is a measured object, so it is shown in a well rather than offered on a plate — this component does not re-implement that pairing, it passes through to it. Reach for <code>Frame</code> directly when you need the eyebrow, a deeper well, or actions that are real controls.</>,],preview:<ChartContainer title="Weekly signups" meta="Q3" description="Weekly signups over the last six weeks." legend={[{label:"This week",color:"var(--td-brand)"},{label:"Last week",color:"var(--td-accent)"}]}><svg viewBox="0 0 200 60" style={{width:"100%",height:"120px",color:"var(--td-brand)"}}><polyline fill="none" stroke="currentColor" strokeWidth="2" points="0,50 40,40 80,20 120,30 160,10 200,25"/></svg></ChartContainer>},
 {id:"filter-bar",name:"FilterBar",group:"Surfaces & data",summary:"Multi-select chip row with counts, per-chip color, disabled chips, and clear-all action.",code:`import { FilterBar } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FilterBar options={[\n  { value: "open", label: "Open", count: 42, color: "brand" },\n  { value: "in-review", label: "In review", count: 12 },\n]} />`,options:[["options[]",`{ value, label, count?, color?, disabled? }`,<>One chip each. <code>count</code> prints the number in the machine face; <code>color</code> takes <code>"brand"</code> or <code>"accent"</code>; <code>disabled</code> greys the chip without removing it.</>],["value / defaultValue",`string[]`,<>An <strong>array</strong> — this is multi-select. Pass <code>value</code> with <code>onValueChange</code> to control it, or <code>defaultValue</code> to leave it uncontrolled.</>],["clearLabel",`string · default "Clear filters"`,<>The words on the clear-all control, which only appears once something is selected.</>],],notes:[<><strong>Chips are toggles, not links.</strong> Each is a button carrying <code>aria-pressed</code>, so a screen reader hears the on or off state rather than having to infer it from the styling.</>,<>Clearing calls <code>onValueChange</code> with an empty array like any other change, so a controlled bar needs no special case for it.</>,<>Disabled chips are deliberately left in place. Removing an option because it currently has no rows tells the reader the filter does not exist.</>,<><code>label</code> names the group. Set it whenever there is more than one filter bar on a page — “Status filters”, “Owner filters”.</>,],preview:<FilterBar options={[{value:"open",label:"Open",count:42,color:"brand"},{value:"in-review",label:"In review",count:12},{value:"done",label:"Done",count:128,color:"accent"},{value:"archived",label:"Archived",disabled:true}]} defaultValue={["open"]}/>},

 {id:"application-shell",name:"ApplicationShell",group:"App patterns",summary:"Grouped sidebar navigation, identity slot, main page header, and content area for signed-in app pages.",code:`import { ApplicationShell } from "@mithtech-bengaluru/tonaldepth-react";\n\n<ApplicationShell identity={<b>Acme</b>}\n  title="Overview" description="Signals from every workspace."\n  sections={[\n    { label: "Work", items: [{ label: "Dashboard", href: "#", current: true }, { label: "Projects", href: "#", count: 12 }] },\n  ]}\n>\n  Content lives here.\n</ApplicationShell>`,options:[["sections[]",`{ label?, items }`,<>Groups in the sidebar. A section's <code>label</code> is optional, so an ungrouped first block is just a section without one.</>],["sections[].items[]",`{ label, href, current?, count? }`,<><code>current</code> marks the open page; <code>count</code> prints a number on the right of the row in the machine face.</>],["identity",`ReactNode`,<>The top-left slot: the workspace, the tenant, the account switcher.</>],["sidebarFooter",`ReactNode`,<>The bottom of the sidebar — a plan badge, a build number, a support link.</>],],notes:[<><strong><code>title</code> is the page header, not the app name.</strong> The shell renders the header for you from <code>title</code>, <code>description</code> and <code>actions</code>; the app's own name belongs in <code>identity</code>.</>,<><code>children</code> is the content area, and it owns its own layout. Put a <a href="#page-patterns">page pattern</a> in it rather than laying the page out here.</>,<><code>sidebarLabel</code> names the sidebar navigation landmark; it defaults to “Application navigation”.</>,<>Marking two items <code>current</code> is not prevented and is almost always a routing bug. One page, one current item.</>,],preview:<ApplicationShell identity={<b>Acme</b>} title="Overview" description="Signals from every workspace." sections={[{label:"Work",items:[{label:"Dashboard",href:"#",current:true},{label:"Projects",href:"#",count:12}]},{label:"Team",items:[{label:"Members",href:"#"},{label:"Billing",href:"#"}]}]} sidebarFooter={<Badge variant="success">Verified</Badge>} actions={<Button size="sm">Invite</Button>}><Card><CardHeader><CardTitle>Recent activity</CardTitle></CardHeader><CardContent>Signals appear here.</CardContent></Card></ApplicationShell>},
 {id:"page-patterns",name:"Page patterns",group:"App patterns",summary:"Composed page templates: DashboardPage, DashboardPanel, DataManagementPage, PageState.",code:`import { DashboardPage, DashboardPanel, KpiCard, KpiGrid, PageState } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DashboardPage title="Overview"\n  metrics={<KpiGrid><KpiCard label="Open" value="42" trend="up" delta="+6"/></KpiGrid>}\n>\n  <DashboardPanel title="Recent activity" span={2}>...</DashboardPanel>\n</DashboardPage>`,options:[["DashboardPanel span",`1 | 2 | "full" · default 1`,<>How many bento columns the panel takes. <code>"full"</code> is the whole row — for the one panel a dashboard is actually about.</>],["PageState variant",`"empty" | "loading" | "error"`,<>Which of the three non-content states the page is in. Required: a PageState with no variant is a state nobody has decided.</>],["DashboardPage filters / metrics",`ReactNode`,<>Two optional bands between the header and the bento — a <a href="#filter-bar">FilterBar</a> and a <a href="#kpi">KpiGrid</a> are what they are shaped for.</>],["DataManagementPage toolbar / footer",`ReactNode`,<>The band above the panel and the row below it — search and bulk actions above, pagination and counts below.</>],],notes:[<><strong>Four exports.</strong> <code>DashboardPage</code> is a header plus optional filters and metrics over a bento grid. <code>DashboardPanel</code> is one cell of that grid. <code>DataManagementPage</code> is a header, a toolbar, one panel and a footer — the list-and-table page. <code>PageState</code> is the empty, loading and error state.</>,<>A <code>DashboardPanel</code> with a <code>title</code> is labelled by it automatically, so each cell is its own landmark for a screen reader. A panel with no title falls back to whatever <code>aria-labelledby</code> you pass. Its <code>meta</code> sits opposite the title in the panel's head — a count, a period, a last-updated stamp — and the head only renders when one of the two is present. <code>span</code> is how many grid columns the cell takes.</>,<><strong><code>DataManagementPage</code> is the list-and-table page.</strong> <code>title</code>, an optional <code>description</code> and <code>actions</code> make the header; <code>toolbar</code> is the row for a <a href="#filter-bar">FilterBar</a> or a <a href="#search-bar">SearchBar</a>; <code>children</code> fill the single panel below it — usually a <a href="#table">Table</a> in its <code>TableContainer</code>; and <code>footer</code> is the result count or the pager.</>,<><code>PageState</code> takes <code>title</code>, an optional <code>description</code>, an <code>illustration</code> slot and one <code>action</code>. One action — a state offering three ways out is a state nobody escapes.</>,<>These are compositions of the primitives, not a layout engine. When a page does not fit one, build it out of <a href="#card">Card</a>, <a href="#frame">Frame</a> and the grids rather than bending a pattern.</>,],preview:<div className="stack"><DashboardPage title="Overview" description="Signals across every workspace." metrics={<KpiGrid><KpiCard label="Open" value="42" delta="+6" trend="up"/><KpiCard label="Resolved" value="128" delta="+18%" trend="up"/></KpiGrid>}><DashboardPanel title="Recent activity" span="full">Signals appear here.</DashboardPanel></DashboardPage><DataManagementPage title="Engagements" description="Every active implementation, and who is on it." actions={<Button size="sm" variant="primary">New engagement</Button>} footer={<span className="hint">3 of 24 shown</span>}><TableContainer><Table><TableHead><TableRow><TableHeader>Client</TableHeader><TableHeader>Platform</TableHeader><TableHeader>Stage</TableHeader></TableRow></TableHead><TableBody><TableRow><TableCell>Rework Industries</TableCell><TableCell>ERPNext</TableCell><TableCell><Badge variant="success">Live</Badge></TableCell></TableRow><TableRow><TableCell>Coastal Freight</TableCell><TableCell>Medusa</TableCell><TableCell><Badge>Build</Badge></TableCell></TableRow><TableRow aria-selected="true"><TableCell>Northwind Foods</TableCell><TableCell>n8n</TableCell><TableCell><Badge variant="brand">Discovery</Badge></TableCell></TableRow></TableBody></Table></TableContainer></DataManagementPage><PageState variant="empty" title="Nothing yet" description="Add your first project to see signals here." action={<Button>New project</Button>}/></div>},
 {id:"filament-button",name:"FilamentButton",group:"Actions",summary:"A tab button that reports its state with a lit filament instead of a fill. Three parts, two of which move independently: the row sinks as it is reached for, the icon tile rides above the row and sinks with it, and the filament only lights \u2014 off, dim on hover, white-hot at the press, full while held. The strip runs down the inline-start edge, or along the top for a horizontal bar.",code:`import { FilamentButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Four states. \`active\` is the one that survives the pointer leaving. */}\n<FilamentButton label="Overview" icon={<GridIcon />} />\n<FilamentButton label="Settings" icon={<GearIcon />} active />\n\n{/* Horizontal, for a bar. */}\n<FilamentButton edge="top" label="Alerts" icon={<BellIcon />} tone="brand" />\n\n{/* The collapsed rail — glyph only, so it needs a name. */}\n<FilamentButton size="sm" icon={<GridIcon />} aria-label="Overview" />`,options:[["active",`boolean · default false`,<>Lit and held — the tab whose panel is open. This is the fourth state, and it is the one hover cannot do: the filament stays on when the pointer leaves.</>],["icon",`ReactNode`,<>Goes in the tile — a square button of its own inside the row, raised at rest and sinking as the row is reached for. Pass a filled glyph: the glyph is the lamp and it lights by colour alone, so an outline mark has nothing to light.</>],["tone",`"green" | "brand" | "accent" | "error" · default "green"`,<>What the filament lights. These are the system's categories, not free colour.</>],["edge",`"start" | "top" · default "start"`,<><code>start</code> runs the filament down the inline-start edge — the vertical tab. <code>top</code> lays it along the top edge, for a horizontal bar.</>],["size",`"sm" | "md" · default "md"`,<>The housing. <code>sm</code> is the collapsed-rail form, which is where the icon-only variant belongs.</>],["glow",`string`,<>Any CSS colour, overriding the tone. Mixed at the <code>--td-filament-*</code> strengths, so it still rides the same four-state ladder.</>],],notes:[<><strong>Three parts, and two of them move.</strong> The <em>row</em> is one button — it sinks on hover and deeper on the press. The <em>tile</em> holding the glyph is the other — it rides above the row at rest and sinks with it, keeping a shadow in every state so it always reads as its own control. The <em>filament</em> never moves or grows; it only lights. Nothing is required of you to get this: pass a <code>label</code> and an <code>icon</code>.</>,<><strong>The glyph lights by colour, never by glow.</strong> It steps unlit ink \u2192 the tone \u2192 white-hot at the press \u2192 full tone while held. Do not add a <code>drop-shadow</code> to an icon you pass in: a halo behind a glyph this small paints as a dark smear, and the design system's own row does not have one.</>,<><strong>Four states, not three:</strong> off at rest, dim on hover, held while its panel is open, and brightest for the press. If two of them look the same, the composition has lost a step.</>,<><strong>Omit <code>label</code> for the icon-only rail form and pass <code>aria-label</code></strong> — a glyph is not a name.</>,<><code>icon</code> must be a filled glyph. An outline has almost no alpha for the filament's glow to bloom from.</>,<>This is the button on its own. For a whole tab set with the keyboard pattern and the panels wired up, use <a href="#side-tabs">SideTabs</a> — it is built from this.</>,<>Native button attributes pass through, <code>disabled</code> and <code>onClick</code> included.</>,],preview:<div style={{display:"grid",gap:20}}><div style={{display:"flex",gap:8,flexWrap:"wrap"}}><FilamentButton label="Rest" icon={<IGrid/>}/><FilamentButton label="Held" icon={<IGear/>} active/><FilamentButton label="Papaya" icon={<IBell/>} tone="brand" active/><FilamentButton label="Azure" icon={<IGrid/>} tone="accent" active/><FilamentButton label="Disabled" icon={<IGear/>} disabled/></div><div style={{display:"flex",gap:8,flexWrap:"wrap"}}><FilamentButton edge="top" label="Top edge" icon={<IGrid/>}/><FilamentButton edge="top" label="Top, held" icon={<IGear/>} active/></div><div style={{display:"flex",gap:8}}><FilamentButton size="sm" icon={<IGrid/>} aria-label="Overview"/><FilamentButton size="sm" icon={<IGear/>} aria-label="Settings" active/><FilamentButton size="sm" icon={<IBell/>} aria-label="Alerts" tone="error" active/></div></div>},
 {id:"side-tabs",name:"SideTabs",group:"Navigation",summary:"The sideways tab. A vertical rail whose selection is reported by a lit filament rather than a fill — with labels on desktop, collapsed to glyphs in a narrow rail, or laid horizontally for mobile. Full WAI-ARIA tabs keyboard pattern.",code:`import { SideTabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SideTabs\n  label="Account"\n  items={[\n    { id: "overview", label: "Overview", icon: <GridIcon />, panel: <p>…</p> },\n    { id: "settings", label: "Settings", icon: <GearIcon />, panel: <p>…</p> },\n  ]}\n/>\n\n{/* layout="rail" hides the labels; layout="bar" lays it horizontally. */}\n<SideTabs layout="bar" items={items} />`,options:[["layout",`"sidebar" | "rail" | "bar" · default "sidebar"`,<><code>sidebar</code> is the desktop rail with labels. <code>rail</code> collapses to glyphs only. <code>bar</code> lays the tabs horizontally with the filament along the top — the mobile form, and the one for when vertical space is the scarce axis.</>],["items[]",`{ id, label, icon?, panel?, ariaLabel?, disabled? }`,<><code>id</code> is the stable key and what <code>value</code> and <code>onValueChange</code> speak in. <code>panel</code> is the content for that tab.</>],["tone",`"green" | "brand" | "accent" | "error" · default "green"`,<>The filament's colour when lit, shared with <a href="#filament-button">FilamentButton</a>.</>],["value / defaultValue",`string`,<>Control it with <code>value</code> and <code>onValueChange</code>, or leave it uncontrolled. With neither, the first enabled tab is selected.</>],],notes:[<><strong>Every tab is a <a href="#filament-button">FilamentButton</a>,</strong> so each one carries the same three parts: a row that sinks as it is reached for, an icon tile that rides above the row and sinks with it, and a filament that only lights. Give each item an <code>icon</code> and the tile appears; leave it off and the row is label-only.</>,<><strong><code>rail</code> hides the labels, so each item needs an <code>icon</code></strong> — and an <code>ariaLabel</code> too whenever <code>label</code> is not a plain string, because there is no visible text to fall back on.</>,<><strong>Selection follows focus.</strong> Arrows move — up and down in <code>sidebar</code> and <code>rail</code>, left and right in <code>bar</code> — Home and End jump to the ends, and disabled tabs are skipped rather than focused and refused.</>,<>The list is a roving tabstop, so one Tab press moves from the rail into the open panel.</>,<><code>label</code> names the tab list for a screen reader. Set it whenever a page has more than one.</>,<><code>panel</code> is optional — leave it off and the component is a selection rail whose content you render yourself from <code>onValueChange</code>.</>,],preview:<div style={{display:"grid",gap:28}}><SideTabs label="Desktop sidebar" items={[{id:"overview",label:"Overview",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The sidebar form. The filament stays lit while this panel is open — that is the fourth state, and it is the one hover cannot do.</p>},{id:"settings",label:"Settings",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Arrow keys move between tabs and selection follows focus. Home and End jump to the ends.</p>},{id:"alerts",label:"Alerts",icon:<IBell/>,panel:<p className="sub" style={{margin:0}}>A disabled tab is skipped by the arrows rather than focused and refused.</p>},{id:"billing",label:"Billing",disabled:true,panel:<p>Unreachable.</p>}]}/><SideTabs layout="bar" tone="brand" label="Mobile bar" items={[{id:"a",label:"Despatch",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The bar form puts the filament along the top edge. Use it when vertical space is the scarce axis.</p>},{id:"b",label:"Returns",icon:<IBell/>,panel:<p className="sub" style={{margin:0}}>The list scrolls itself rather than taking the page's horizontal scroll with it.</p>},{id:"c",label:"Invoices",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Third panel.</p>}]}/><SideTabs layout="rail" tone="accent" label="Collapsed rail" items={[{id:"a",label:"Overview",icon:<IGrid/>,panel:<p className="sub" style={{margin:0}}>The rail hides its labels, so each tab takes its name from the label string.</p>},{id:"b",label:"Settings",icon:<IGear/>,panel:<p className="sub" style={{margin:0}}>Shorter filament, smaller housing — for a collapsed sidebar or a mobile rail.</p>}]}/></div>},
 {id:"split-button",name:"SplitButton",group:"Actions",summary:"One action with its alternatives folded behind a disclosure. Give it a default and it acts at once, with the menu as an override; withhold the default and it waits until the reader chooses, for when the choice is load-bearing.",code:`import { SplitButton } from "@mithtech-bengaluru/tonaldepth-react";\n\nconst CHANNELS = [\n  { id: "whatsapp", label: "WhatsApp", detail: "+91 80 4718 2200", icon: <WhatsAppIcon /> },\n  { id: "call", label: "Call", detail: "+91 80 4718 2200", icon: <CallIcon /> },\n  { id: "email", label: "Email", detail: "hello@mith.tech", icon: <EmailIcon /> },\n];\n\n{/* Defaulted — "any" takes the first enabled action and fires at once. */}\n<SplitButton actions={CHANNELS} defaultAction="any" onAction={a => open(a.id)} />\n\n{/* Forced select — inert until the reader picks a channel. */}\n<SplitButton actions={CHANNELS} placeholder="Contact us via…" />`,options:[["defaultAction",`an action id`,<>The primary half fires that action at once, and the menu is an override.</>],["defaultAction",`"any"`,<>Takes the first enabled action. The right default for a “contact us” where every channel reaches the same desk.</>],["defaultAction",`omitted`,<><strong>Forced select.</strong> The primary half stays inert until the reader picks a channel — for when the choice is load-bearing and a wrong default costs them something.</>],["actions[]",`{ id, label, icon?, detail?, href?, disabled? }`,<><code>detail</code> is the second line in the menu — the number, the address, the handle. <code>href</code> turns the primary half into an anchor when that action is the chosen one.</>],["placeholder",`ReactNode · default "Choose an option"`,<>What the primary half reads before anything is chosen. Only visible in forced-select mode.</>],["menuLabel",`string · default "More options"`,<>The accessible name of the disclosure half.</>],],notes:[<><strong>Two callbacks, two questions.</strong> <code>onAction</code> fires with the action that ran — both when the primary half is pressed and when one is picked from the menu. <code>onValueChange</code> only reports which action is now chosen.</>,<><code>value</code> makes the choice controlled; without it the button keeps its own.</>,<>Every label is rendered stacked in one grid cell, so the housing is as wide as its longest option and does not resize when the selection changes.</>,<>In the menu: arrows move, Home and End jump, Escape closes, and a click outside dismisses it. A disabled action stays listed and is skipped.</>,<>The two halves share one housing and are divided by a carved seam. Neither half is filled with the brand colour — the chosen channel is reported by its glyph.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><SplitButton defaultAction="any" menuLabel="Choose a channel" actions={[{id:"whatsapp",label:"WhatsApp",detail:"+91 80 4718 2200",icon:<IWhatsApp/>},{id:"call",label:"Call",detail:"+91 80 4718 2200",icon:<IPhone/>},{id:"email",label:"Email",detail:"hello@mith.tech",icon:<IMail/>}]}/><SplitButton placeholder="Contact us via…" menuLabel="Choose a channel" actions={[{id:"whatsapp",label:"WhatsApp",detail:"+91 80 4718 2200",icon:<IWhatsApp/>},{id:"call",label:"Call",detail:"+91 80 4718 2200",icon:<IPhone/>},{id:"email",label:"Email",detail:"hello@mith.tech",icon:<IMail/>},{id:"post",label:"Post",detail:"Not available",icon:<IMail/>,disabled:true}]}/></div>},
 {id:"search-bar",name:"SearchBar",group:"Forms",summary:"A search field, carved into the surface rather than raised — a place to put something is never lifted. Optional suggestion listbox following the ARIA combobox pattern, in three sizes.",code:`import { SearchBar } from "@mithtech-bengaluru/tonaldepth-react";\n\n<SearchBar placeholder="Search products" onSubmit={q => run(q)} />\n\n{/* With suggestions it is a combobox — arrows move, Escape closes it\n    without clearing what was typed. */}\n<SearchBar\n  suggestions={[{ id: "erpnext", label: "ERPNext", detail: "22 products" }]}\n  onSuggestionSelect={s => go(s.id)}\n  showSubmit\n/>`,options:[["size",`"sm" | "md" | "lg" · default "md"`,<>The field's height and type size. <code>lg</code> is the page-level search; <code>sm</code> filters a table.</>],["block",`boolean · default false`,<>Fills the container instead of taking the field's own natural width.</>],["showSubmit",`boolean · default false`,<>Renders a visible submit button. Enter submits either way, so this is about affordance rather than function.</>],["suggestions[]",`{ id, label, detail? }`,<>Rendered as a listbox under the field, <strong>exactly as given</strong>. <code>detail</code> is the second line — the section, the category, the count.</>],["value / defaultValue",`string`,<>Control the query with <code>value</code> and <code>onValueChange</code>, or leave it uncontrolled with <code>defaultValue</code>.</>],],notes:[<><strong>It does no matching.</strong> The suggestion list renders in the order you pass it, so the consumer keeps control of ranking — mith.tech drives this from Fuse.js, and a server route or a plain <code>filter</code> works the same way. <strong>Sort before passing.</strong></>,<><strong>With <code>suggestions</code> it is an ARIA 1.2 combobox.</strong> The field keeps focus while <code>aria-activedescendant</code> moves through the list; Enter takes the highlighted suggestion, or submits the query when nothing is highlighted; Escape closes the list <em>without</em> clearing what was typed.</>,<><code>onSubmit</code> fires on Enter and on the submit button, with the current query. <code>onSuggestionSelect</code> fires instead when a suggestion is taken.</>,<>A blur that lands inside the component — onto a suggestion — is not a dismissal. Only focus leaving the whole thing closes the list.</>,<>The field is carved into the surface rather than raised: a place to put something is never lifted. The magnifier is a mark, not a control, and takes no glow.</>,<><code>clearLabel</code> and <code>submitLabel</code> are accessible names, so translate them with the rest of the page.</>,],preview:<div style={{display:"grid",gap:20}}><SearchBar placeholder="Search components"/><SearchBar size="lg" showSubmit defaultValue="erp" placeholder="Search products" suggestions={[{id:"erpnext",label:"ERPNext implementation",detail:"Services · 9 pages"},{id:"medusa",label:"Medusa storefront",detail:"Services · 4 pages"},{id:"n8n",label:"n8n automation",detail:"Services · 6 pages"}]}/><SearchBar size="sm" placeholder="Filter rows"/></div>},
 {id:"progress",name:"Progress",group:"Feedback",summary:"A determinate meter. The track is carved into the surface and the filled length is the only thing that carries colour \u2014 it is a measured quantity, like a chart series, so it is allowed one.",code:`import { Progress } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The whole meter line: what, how far, and the percentage. */}\n<Progress label="Deployment" detail="4 of 12" value={33} />\n\n{/* Bare, for a meter inside a row that already says what it is. */}\n<Progress value={75} showValue={false} aria-label="Migration" />\n\n{/* Only when the total genuinely is not known. */}\n<Progress label="Indexing" indeterminate />`,options:[["value",`number`,<>0\u2013100, clamped. It is rounded for display and for <code>aria-valuenow</code>, so the number a reader hears is the number they see.</>],["tone",`"brand" | "accent" | "green" | "error" \u00b7 default "brand"`,<>Which category the filled length carries. Use it to say what <em>kind</em> of progress this is \u2014 <code>error</code> for a budget being consumed, <code>green</code> for a target being met \u2014 not to make a row look different from its neighbour.</>],["label / detail",`ReactNode`,<><code>label</code> is what is progressing; <code>detail</code> is the machine face of the count (<code>4 of 12</code>) and is set in mono beside it. Both are optional and the head disappears when neither is present.</>],["showValue",`boolean \u00b7 default true`,<>The percentage at the end of the meter line. Turn it off where the count in <code>detail</code> already says it.</>],["indeterminate",`boolean \u00b7 default false`,<>A short length sweeping the track, and no <code>aria-valuenow</code>. Reach for it only when the total is genuinely unknown.</>],],notes:[<><strong>Name it.</strong> With no <code>label</code>, pass <code>aria-label</code> \u2014 a bare meter reaches a screen reader as an unnamed number. A string <code>label</code> is used automatically.</>,<><strong>A determinate bar is the better answer.</strong> <code>indeterminate</code> animates forever and tells the reader nothing; if you can compute a fraction, compute it. Under reduced motion the sweep stops rather than spinning silently.</>,<>The filled length carries colour because it is data. Nothing else here does \u2014 the track is depth, and there is no tinted plate behind the row.</>,<>For a step-by-step sequence rather than a fraction, use <a href="#timeline">Timeline</a>.</>,],preview:<div className="stack" style={{gap:18}}><Progress label="Deployment" detail="4 of 12" value={33}/><Progress label="Migration" detail="9 of 12" value={75} tone="accent"/><Progress label="Budget consumed" detail="\u20b98.2L of \u20b99L" value={91} tone="error"/><Progress label="Indexing" indeterminate/></div>},
 {id:"copy-chip",name:"CopyChip",group:"Actions",summary:"A machine value the reader can take with them \u2014 a host, a command, a URL. Set in mono, and it reports its own success in ink and glyph rather than behind a tinted plate.",code:`import { CopyChip } from "@mithtech-bengaluru/tonaldepth-react";\n\n<CopyChip value="ssh root@po5.mith.tech" />\n\n{/* A long value with a short face. */}\n<CopyChip value="https://github.com/mithtech/commercely" label="commercely repo" />\n\n{/* Hook it up to whatever you count. */}\n<CopyChip value={key} onCopied={() => track("api-key-copied")} />`,options:[["value",`string`,<>What goes on the clipboard, and the visible text unless <code>label</code> overrides it.</>],["label",`ReactNode`,<>A shorter face for a long value. The clipboard still gets <code>value</code>, so the two can differ freely.</>],["holdFor",`number \u00b7 default 1600`,<>How long the copied state holds, in ms.</>],["copiedLabel",`string \u00b7 default "Copied"`,<>Announced in the live region while the copied state holds. Translate it with the rest of the page.</>],["onCopied",`(value: string) => void`,<>Fires after a successful write \u2014 the place to count the event.</>],],notes:[<><strong>Success is ink, not a fill.</strong> The glyph swaps to the accept mark and the ink steps to green for a moment; the housing does not change colour. A category arrives as ink and light, never as a wash, so the design system's own green plate is deliberately not reproduced.</>,<><strong>It needs a secure context.</strong> <code>navigator.clipboard</code> is unavailable on plain <code>http://</code>. Where it is missing the chip selects its own text instead, so the reader can copy by hand rather than pressing a dead button \u2014 but the copied state does not fire, because nothing was copied.</>,<><strong>It names itself.</strong> The accessible name is <code>Copy {"{value}"}</code>, because the visible text is the value and says nothing about what the control does. Pass <code>aria-label</code> to override. The copied state is announced through a polite live region, so it is heard as well as seen.</>,<>Everything native passes through \u2014 <code>disabled</code>, <code>onClick</code> (yours runs first; call <code>preventDefault</code> to stop the copy), <code>title</code>.</>,],preview:<div className="stack" style={{gap:10,alignItems:"flex-start"}}><CopyChip value="ssh root@po5.mith.tech"/><CopyChip value="https://github.com/mithtech/commercely" label="commercely repo"/><CopyChip value="pnpm add @mithtech-bengaluru/tonaldepth-react"/><p className="hint" style={{margin:0}}>Press one: the glyph becomes the accept mark and the ink steps to green. The housing holds its colour throughout.</p></div>},
 {id:"toc",name:"TableOfContents",group:"Navigation",summary:"The on-this-page rail. The seam down its side is a filament \u2014 always present, off and grey \u2014 and the section being read lights its own segment. Nothing moves, so the rail never reflows as the reader scrolls.",code:`import { TableOfContents } from "@mithtech-bengaluru/tonaldepth-react";\n\n<TableOfContents\n  current={active}\n  items={[\n    { id: "scope", label: "What the engagement covers" },\n    { id: "timeline", label: "Timeline and governance gates" },\n    { id: "gate-1", label: "Gate 1 \u2014 discovery sign-off", sub: true },\n    { id: "cost", label: "What it costs" },\n  ]}\n/>`,options:[["items[]",`{ id, label, sub? }`,<><code>id</code> is the heading's id without the <code>#</code> \u2014 it becomes the href and is what <code>current</code> is matched against. <code>sub</code> indents an entry as a second-level heading. Two levels is the limit on purpose: a rail deeper than that is a document outline, not a way to move around a page.</>],["current",`string`,<>The id of the section being read. Lights that entry's filament and rests the row recessed.</>],["label",`ReactNode \u00b7 default "On this page"`,<>The heading above the list. Pass <code>null</code> to drop it where the surrounding layout already says it.</>],["ariaLabel",`string \u00b7 default "On this page"`,<>Names the navigation landmark. Keep it even when <code>label</code> is dropped \u2014 it is the only name the landmark has.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href, the children and the <code>aria-current</code> state, return the element.</>],],notes:[<><strong>It does not track scrolling, and that is deliberate.</strong> You pass <code>current</code> \u2014 from an IntersectionObserver, or your router. Owning it here would mean guessing a root margin that suits every page, and it never does. The rail is the display; deciding which section is being read is the page's job.</>,<><strong>The seam is one line that lights, not a line that appears.</strong> Off is grey glass, so the rail's geometry is identical in every state and nothing reflows under a scrolling reader.</>,<>Each entry takes the row press \u2014 hover sinks it, the press sinks it deeper, and the current one rests recessed. <code>aria-current="true"</code> is set on that entry, which is what a screen reader reads.</>,<>In-page anchors are the default and are usually right here. Reach for <code>renderLink</code> when the rail spans routes rather than headings.</>,],preview:<TableOfContents current="timeline" items={[{id:"scope",label:"What the engagement covers"},{id:"timeline",label:"Timeline and governance gates"},{id:"gate-1",label:"Gate 1 \u2014 discovery sign-off",sub:true},{id:"gate-2",label:"Gate 2 \u2014 cutover readiness",sub:true},{id:"cost",label:"What it costs"},{id:"next",label:"Next step"}]}/>},
 {id:"range",name:"Range",group:"Forms",summary:"A single-value slider on a carved track. A real input[type=range], so the keyboard, the pointer and every assistive technology behave natively \u2014 only the track and the thumb are restyled.",code:`import { Range } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Range\n  label="Team size"\n  min={1}\n  max={40}\n  defaultValue={12}\n  format={n => n + ' people'}\n  showBounds\n/>\n\n{/* Controlled. */}\n<Range label="Budget" value={budget} onChange={e => setBudget(+e.target.value)} max={2000000} step={50000} />`,options:[["value / defaultValue",`number`,<>Controlled with <code>value</code> plus <code>onChange</code>; uncontrolled with <code>defaultValue</code>. Left off entirely it starts at <code>min</code>.</>],["min / max / step",`number \u00b7 default 0 / 100 / 1`,<>The range and its granularity, passed straight to the input, so the keyboard steps by <code>step</code> and Page Up/Down by ten of them.</>],["label",`ReactNode`,<>What is being set. It renders a real <code>label</code> wired to the input, so clicking it focuses the slider.</>],["format",`(value: number) => ReactNode`,<>The current value in the reader's own units \u2014 <code>\u20b94,50,000</code>, <code>12 weeks</code>. Shown in mono at the end of the label row, and reused for the bounds when <code>showBounds</code> is on.</>],["showBounds",`boolean \u00b7 default false`,<>Prints the min and max under the track. Worth it when the scale is not obvious from the value alone.</>],],notes:[<><strong>It is a real range input.</strong> Arrow keys, Home/End, Page Up/Down, touch dragging and every screen reader's slider mode work because nothing was rebuilt \u2014 the track and thumb are reached through the vendor pseudo-elements. That is also why there is no two-handle form here: a native range has one thumb, and a second one is a different component rather than a prop.</>,<><strong>Give it a name.</strong> With no <code>label</code>, pass <code>aria-label</code>. A slider announced only as a number tells the reader how much of nothing.</>,<>The filled length is the one thing carrying colour, for the same reason <a href="#progress">Progress</a>'s bar is: it is a measured quantity rather than decoration.</>,<>Everything native passes through \u2014 <code>disabled</code>, <code>name</code>, <code>form</code>, <code>onInput</code>, <code>aria-*</code>.</>,],preview:<div className="stack" style={{gap:22}}><Range label="Team size" min={1} max={40} defaultValue={12} format={n=>`${n} people`} showBounds/><Range label="Go-live window" min={4} max={52} defaultValue={11} step={1} format={n=>`${n} weeks`}/><Range label="Disabled" defaultValue={40} disabled format={n=>`${n}%`}/></div>},
 {id:"data-list",name:"DataList",group:"Surfaces & data",summary:"Four to six fields about one record. A table answers how records compare; this answers what one record is \u2014 below about six fields a header row is overhead, and the field name belongs beside its value.",code:`import { DataList } from "@mithtech-bengaluru/tonaldepth-react";\n\n<DataList\n  label="Engagement detail"\n  rows={[\n    { label: "Engagement", value: "Commercely \u00b7 Medusa replatform", meta: "11 weeks" },\n    { label: "Stack", value: "Medusa \u00b7 PostgreSQL \u00b7 Hetzner", meta: "3 services" },\n    { label: "Owner", value: "Manoj Bhat", href: "/team/manoj" },\n  ]}\n/>`,options:[["rows[]",`{ label, value, meta?, href? }`,<><code>label</code> is the field name, set in mono and upper-cased because it is a key rather than prose. <code>value</code> is the content. <code>meta</code> is the machine face at the end of the row \u2014 a duration, a count, a state. <code>href</code> makes the whole row a link.</>],["label",`string`,<>Names the list for a screen reader. Worth setting when more than one list is on the page.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor, for rows that carry an <code>href</code>. Without it a linked row is a document load.</>],],notes:[<><strong>It is a real definition list.</strong> Each row is a <code>dt</code> and a <code>dd</code>, so a screen reader reads it as pairs rather than as a run of text. That is the reason to reach for this over a two-column <a href="#table">Table</a> with one record in it.</>,<><strong>Rows press, they do not tint.</strong> Hover sinks the row and steps the label to brand ink; a linked row presses deeper. The row itself never takes a colour \u2014 being pointed at is not a category.</>,<><strong>Where the line is.</strong> Four to six fields is the range. More than that and the eye starts scanning for a column, which is what a <a href="#table">Table</a> is for; fewer than three and it is usually just a sentence.</>,<>Below 560px the two columns stack, so the label sits above its value rather than being squeezed into a third of a phone.</>,],preview:<DataList label="Engagement detail" rows={[{label:"Engagement",value:"Commercely \u00b7 Medusa commerce replatform",meta:"11 weeks"},{label:"Stack",value:"Medusa \u00b7 PostgreSQL \u00b7 Hetzner",meta:"3 services"},{label:"Status",value:<Badge variant="success">Live</Badge>,meta:"since Jun"},{label:"Owner",value:"Manoj Bhat",href:"#data-list",meta:"principal"}]}/>},
 {id:"faq",name:"Faq",group:"Marketing",summary:"Questions that open in place. One carved plate with seams between them rather than a stack of cards \u2014 eight raised objects for what is one list reads as eight decisions. Take the plate off and it is the design system's standalone disclosure, which is why there is no second component for that.",code:`import { Faq } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Faq\n  label="Implementation questions"\n  single\n  defaultValue={["cost"]}\n  items={[\n    { id: "cost", question: "What does an ERPNext rollout cost?", answer: <p>Eleven engagements, \u20b96L to \u20b942L.</p> },\n    { id: "time", question: "How long does it take?", answer: <p>Nine to sixteen weeks.</p> },\n  ]}\n/>`,options:[["items[]",`{ id, question, answer }`,<><code>id</code> is the stable key and what <code>value</code> speaks in. <code>answer</code> takes nodes, so a real paragraph, a list or a link all work.</>],["single",`boolean \u00b7 default false`,<>One at a time \u2014 opening a question closes the one before it. Off, any number can be open at once.</>],["variant",`"plate" \u00b7 default`,<>The FAQ block: one carved plate with seams between the questions. Reach for it whenever the list is the section.</>],["variant",`"seam"`,<><strong>The standalone disclosure.</strong> The plate comes off and the seams stay, so the list sits directly in the surrounding prose instead of reading as a card. One item in this form <em>is</em> a disclosure \u2014 that is the whole difference between the two things, and the reason there is no second component.</>],["value / defaultValue / onValueChange",`string[]`,<>The open ids. Control it with <code>value</code> plus <code>onValueChange</code>, or seed it with <code>defaultValue</code> to open a question on arrival.</>],["label",`string`,<>Names the list for a screen reader. Worth setting when a page carries more than one.</>],],notes:[<><strong>It is a real disclosure.</strong> Each question is a <code>button</code> with <code>aria-expanded</code>, and the answer is the region it controls \u2014 so the keyboard and a screen reader get the behaviour without anything being reimplemented.</>,<><strong>The answer is hidden with <code>hidden</code>, not with a stylesheet.</strong> The two disagree: a CSS-hidden panel is still found by in-page search in some browsers, which is how a reader ends up scrolled to text they cannot see. The stylesheet honours the attribute rather than overriding it.</>,<>The question row takes the row press, and an open question rests recessed \u2014 the same grammar a selected row uses. The chevron turns and steps its ink; it is a direction mark, not a lamp, so it never glows.</>,<>Each question is wrapped in an <code>h3</code>. If the surrounding page needs a different level, that is a composition change rather than a prop \u2014 raise it upstream rather than nesting the list under a heading that does not fit.</>,<><strong>A disclosure is this component with one item and <code>variant="seam"</code>.</strong> Everything else about it \u2014 the button, <code>aria-expanded</code>, the controlled region, the row press, the chevron \u2014 is already identical, so a second component would only have meant two places to correct every time one of those changed.</>,<>Two things the design system's standalone disclosure does are <strong>not</strong> reproduced in <code>seam</code>. It puts the chevron on the <em>left</em> in its own raised tile, which would be a second anatomy inside one component; and it fills that tile with the brand colour when open, which is the one move the system forbids.</>,],preview:<div style={{display:"grid",gap:28}}><Faq label="Implementation questions" single defaultValue={["cost"]} items={[{id:"cost",question:"What does an ERPNext implementation actually cost?",answer:<p style={{margin:0}}>Across eleven engagements, \u20b96L to \u20b942L. The spread is data migration and the number of integrations, not the licence \u2014 there is not one.</p>},{id:"time",question:"How long does it take?",answer:<p style={{margin:0}}>Nine to sixteen weeks from discovery to go-live, running in parallel with your existing system until cutover.</p>},{id:"host",question:"Where does it run?",answer:<p style={{margin:0}}>Your infrastructure or ours \u2014 self-hosted Docker on a VPS. The source and the data stay in your hands either way.</p>}]}/><Faq variant="seam" label="Standalone disclosure" items={[{id:"how",question:"What happens when the content is taller than the viewport?",answer:<p style={{margin:0}}>The answer grows the page. Nothing scrolls inside the panel and nothing is capped \u2014 a reader who opened a question wants all of the answer, and a panel that scrolls inside a scrolling page is two scrollbars for one piece of text.</p>}]}/></div>},
 {id:"link-cells",name:"LinkCells",group:"Marketing",summary:"The where-to-next grid at the foot of a page. The whole cell is the target, so there is no separate read-more link to miss.",code:`import { LinkCells } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LinkCells\n  label="Keep reading"\n  items={[\n    { kicker: "Guide", title: "Migrating from Tally", href: "/services/migration/tally-to-erpnext" },\n    { kicker: "Pricing", title: "What an implementation costs", detail: "Eleven engagements, itemised.", href: "/pricing" },\n  ]}\n/>`,options:[["items[]",`{ href, title, kicker?, detail? }`,<><code>kicker</code> is the category above the title \u2014 small caps, a word or two. <code>detail</code> is one line under it, for a destination whose title does not explain itself. Both are optional.</>],["label",`string`,<>Names the navigation landmark. A page with two of these needs it.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Without it every cell is a document load.</>],],notes:[<><strong>The cell is the link, not a card with a link in it.</strong> That is what makes the whole area clickable and keeps one tab stop per destination. Do not put a button inside a cell \u2014 a control inside a link is unreachable by keyboard in the order a reader expects.</>,<>The arrow moves sideways and steps its ink on hover. It is a direction mark, not a lamp: it never glows, because a glow would report state and there is no state here.</>,<>The grid reflows on its own from 230px, so the count adapts to the column rather than being set.</>,],preview:<LinkCells label="Keep reading" items={[{kicker:"Guide",title:"Migrating from Tally to ERPNext",detail:"The cutover that runs in parallel.",href:"#link-cells"},{kicker:"Pricing",title:"What an implementation actually costs",detail:"Eleven engagements, itemised.",href:"#link-cells"},{kicker:"Case study",title:"Order-to-cash cut to four days",href:"#link-cells"}]}/>},
 {id:"logo-strip",name:"LogoStrip",group:"Marketing",summary:"A wall of real client artwork \u2014 monochrome at rest, full colour on hover. Real marks are third-party proof; a typeset list of names is a claim. Turn on `scroll` and the wall becomes a carousel, for more marks than fit on a line.",code:`import { LogoStrip } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LogoStrip\n  label="Trusted by"\n  items={[\n    { name: "Rework Industries", logo: <img src="/logos/rework.svg" alt="" /> },\n    { name: "Coastal Freight", logo: <img src="/logos/coastal.svg" alt="" />, href: "/case-studies/coastal" },\n  ]}\n/>`,options:[["scroll",`boolean \u00b7 default false`,<><strong>Turns the wall into a carousel.</strong> For more marks than fit on a line, where a wall would either wrap into a block or have to be cut down to the ones that fit. Off, it is the wall.</>],["speed",`number \u00b7 default 32`,<>Seconds for one full pass \u2014 higher is slower. Only used when <code>scroll</code> is on. Slow enough to read a mark, or the strip is decoration.</>],["reverse",`boolean \u00b7 default false`,<>Runs the marks the other way. Two strips in opposite directions is the usual reason to reach for it.</>],["items[]",`{ logo, name, href? }`,<><code>logo</code> is the client's own artwork \u2014 an <code>img</code> or an inline <code>svg</code>. <code>name</code> is required and becomes the mark's alternative text. <code>href</code> makes that mark a link.</>],["label",`ReactNode`,<>The line above the wall \u2014 \u201cTrusted by\u201d, \u201cSelected clients\u201d. Pass <code>null</code> to drop it.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor, for marks that carry an <code>href</code>. Given the class, the href and the children, return the element \u2014 without it a linked mark is a document load.</>],],notes:[<><strong><code>name</code> is not optional, and it is why.</strong> A logo is a picture of a word. The name is always in the DOM and visually hidden, so the wall is a list of organisations to a screen reader rather than a row of unlabelled images. Mark the artwork itself <code>alt=""</code> \u2014 the component supplies the text.</>,<><strong>Pass the real marks.</strong> Eleven client logos are proof; a neat list of typeset names is an assertion. Where a choice trades credibility for tidiness, credibility wins.</>,<>Rest is greyscale at 62% and hover is full colour. It is a filter, not a palette, so a mark that is already monochrome is untouched and no artwork is altered.</>,<>Under reduced motion the scale is dropped and only the colour returns.</>,<><strong>The carousel is a mode, not a second component.</strong> Same items, same greyscale-to-colour treatment, presented as a moving track instead of a wrapping block \u2014 so a logo wall that outgrows its line does not become a different thing to maintain.</>,<><strong>It pauses when a reader engages with it</strong>, on hover and on keyboard focus. A mark that slides out from under the pointer is a link nobody can click, and one that slides away from a focus ring is worse.</>,<><strong>Under <code>prefers-reduced-motion</code> it stops completely</strong> and becomes a track the reader scrolls themselves. Slowing an infinite animation is not honouring that preference \u2014 it is the same animation.</>,<>The marks are rendered twice so the loop has no seam. The second run is <code>inert</code>, which takes it out of the tab order and the accessibility tree together; without that a screen reader reads the whole client list twice.</>,<>The edges are masked rather than cut, so the strip reads as continuing past the frame instead of ending at it.</>,<><strong>The wall is grey until you look at one of them.</strong> Every mark is desaturated and dimmed at rest, and the one under the pointer comes back to full colour and steps forward. It is a <code>filter</code>, so the artwork is never altered and a mark that is already monochrome is unaffected \u2014 and the treatment is on the item rather than the artwork, so an inline SVG, a PNG and a file someone just picked all behave identically.</>,],preview:<div style={{display:"grid",gap:28}}><LogoStrip label="Trusted by \u2014 the wall" items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><LogoStrip scroll speed={26} label="Trusted by \u2014 the carousel" items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><LogoStrip scroll reverse speed={34} label={null} items={[{name:"Rework Industries",logo:<svg viewBox="0 0 120 30" width="96" height="24"><rect x="0" y="6" width="18" height="18" rx="4" fill="#E4572E"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Rework</text></svg>},{name:"Coastal Freight",logo:<svg viewBox="0 0 130 30" width="104" height="24"><circle cx="12" cy="15" r="10" fill="#2E86AB"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Coastal</text></svg>,href:"#logo-strip"},{name:"Northwind Foods",logo:<svg viewBox="0 0 140 30" width="112" height="24"><polygon points="12,4 22,26 2,26" fill="#3B8C4A"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Northwind</text></svg>},{name:"Halver Logistics",logo:<svg viewBox="0 0 130 30" width="104" height="24"><rect x="0" y="8" width="20" height="14" rx="7" fill="#8A5CD8"/><text x="28" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Halver</text></svg>},{name:"Vestry Retail",logo:<svg viewBox="0 0 120 30" width="96" height="24"><path d="M2 22 L11 5 L20 22 Z" fill="#B08D2F"/><text x="26" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Vestry</text></svg>},{name:"Quanta Labs",logo:<svg viewBox="0 0 125 30" width="100" height="24"><circle cx="11" cy="15" r="9" fill="none" stroke="#1E5FA8" strokeWidth="4"/><text x="27" y="21" fontFamily="var(--td-font-ui)" fontSize="14" fontWeight="700" fill="currentColor">Quanta</text></svg>}]}/><p className="hint" style={{margin:0}}>Hover the carousel, or tab into it: it stops while you are engaging with it. With <code>prefers-reduced-motion</code> set it does not move at all and becomes a track you scroll yourself.</p><div><h3 style={{margin:"0 0 8px",fontSize:"0.95rem"}}>Try your own marks</h3><p className="sub" style={{margin:"0 0 12px"}}>The three above are typeset shapes, which is the exact thing this component exists to argue against. Put real artwork through it \u2014 by URL, or from your computer. Nothing is uploaded and nothing is saved.</p><LogoBench/></div></div>},
 {id:"frame",name:"Frame",group:"Surfaces & data",summary:"A raised plate with a well cut into it — the housing anything measured lives inside. Chrome is raised and data is recessed, so a chart or a table reads as data without a single border. Reach for it whenever something is housed rather than offered.",code:`import { Frame, FrameGrid } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* A chart is housed, so it goes in a well. flushContent because a plot\n    already carries its own margins. */}\n<Frame\n  eyebrow="Order to cash"\n  title="Days to collect"\n  description="Median across nine plants, weekly."\n  actions={<Button size="sm" variant="ghost">Export</Button>}\n  footnote={<>Source: ERPNext <code>Sales Invoice</code> · as of 26 Aug 2026</>}\n  flushContent\n>\n  <MyChart />\n</Frame>\n\n{/* depth="flush" cuts no well — for a frame that only supplies a caption. */}\n<Frame title="Notes" depth="flush">…</Frame>\n\n{/* Frames reflow rather than squash. */}\n<FrameGrid min={280}>…</FrameGrid>`,options:[["depth",`"well" | "flush" | "deep" · default "well"`,<>How deep the well is cut. <code>well</code> is the one to reach for. <code>flush</code> cuts no well at all — for a frame only supplying a caption and a rule. <code>deep</code> is for a single hero object on a page with nothing competing with it.</>],["as",`"section" | "figure" | "article" | "div" · default "section"`,<>The element the frame renders as. <code>figure</code> is for a well holding one self-contained object the surrounding prose refers to — a chart, a specimen; it is what <a href="#chart-container">ChartContainer</a> passes. Everything else wants the default.</>],["flushContent",`boolean · default false`,<>Lets the well's content bleed to its edges. Charts usually want this: a plot already carries its own margins and would otherwise sit in two.</>],["FrameGrid min",`number`,<>The smallest a frame may get before the grid drops a column. Frames reflow rather than squash.</>],],notes:[<><strong>Chrome is raised, data is recessed.</strong> That pairing is the whole component — a chart or a table inside it reads as data without a single border being drawn.</>,<>Every slot is optional: <code>eyebrow</code>, <code>title</code>, <code>description</code>, <code>actions</code> and <code>footnote</code>. A Frame with only children is a bare well, which is a legitimate thing to want.</>,<><code>footnote</code> is where the source, the as-of date and the caveat go — under the well, in the quiet face, so the number above it is not carrying its own disclaimer.</>,<><code>actions</code> sits opposite the title: a range picker, an export. Keep it to controls that act on what is in the well.</>,<>Reach for it whenever something is <em>housed</em> rather than offered. A <a href="#card">Card</a> groups; a Frame contains.</>,<><strong>The well's radius is the plate's minus the padding.</strong> That subtraction is what makes it read as a well cut into the plate rather than a sticker stuck on it, and it is why the three values come from <code>--td-frame-pad</code>, <code>--td-frame-radius</code> and <code>--td-well-radius</code> rather than loose radius steps.</>,<>Anything that carries its own plate — a <code>TableContainer</code>, a bento panel — drops it on the way into the well. A raised box inside a trough inverts the whole idea.</>,],preview:<div style={{display:"grid",gap:20}}><Frame eyebrow="Order to cash" title="Days to collect" description="Median across nine plants, weekly." footnote={<>Source: ERPNext <code>Sales Invoice</code> · as of 26 Aug 2026</>}><div style={{display:"flex",alignItems:"flex-end",gap:10,height:120}}>{[38,34,31,29,26,24,21,19].map((v,i)=><div key={i} style={{flex:1,height:`${v*2.4}%`,borderRadius:"4px 4px 0 0",background:`var(--td-series-${i%8+1})`}}/>)}</div></Frame><FrameGrid min={260}><Frame eyebrow="Deep" title="A single hero object" depth="deep"><p className="sub" style={{margin:0}}>A deeper cut, for one thing with nothing competing.</p></Frame><Frame eyebrow="Flush" title="No well" depth="flush"><p className="sub" style={{margin:0}}>Caption and boundary only — nothing is being housed.</p></Frame></FrameGrid></div>},
 {id:"file-tree",name:"FileTree",group:"Navigation",summary:"A repository or docs tree. Every row presses — hover sinks it, the press sinks it deeper, and the file being read rests recessed. The chevron turns to say which way a folder is facing; it is a direction mark, not a lamp, so it never glows.",code:`import { FileTree } from "@mithtech-bengaluru/tonaldepth-react";\n\n<FileTree\n  label="Repository"\n  activeId="checkout"\n  defaultOpen={["root", "storefront"]}\n  nodes={[\n    {\n      id: "root",\n      name: "commercely",\n      children: [\n        { id: "checkout", name: "checkout.tsx", meta: "TSX", href: "/src/checkout.tsx" },\n        { id: "cart", name: "cart.ts", meta: "TS", href: "/src/cart.ts" },\n      ],\n    },\n    { id: "docs", name: "docs", children: [] },\n  ]}\n/>`,options:[["nodes[]",`{ id, name, meta?, href?, children? }`,<><strong><code>children</code> is what makes a node a folder</strong> — present means folder, absent means file. An empty array is a folder with nothing in it, which is a different thing from a file and draws as one. <code>meta</code> is the machine face at the end of the row: a format, a size, a count.</>],["activeId",`string`,<>The file being read. That row rests recessed and takes papaya as ink. Folders are never “active” — a folder's state is open or closed.</>],["open / defaultOpen / onOpenChange",`string[]`,<>The open folder ids. Control them with <code>open</code> plus <code>onOpenChange</code>, or seed them with <code>defaultOpen</code> so a docs sidebar arrives showing the section being read.</>],["onSelect",`(node) => void`,<>Fires when a file row is chosen. A folder row expands instead and never calls it.</>],["href on a node",`string`,<>Renders that file row as an anchor. Without one the row is a button and <code>onSelect</code> is the only way it reports.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. It is given the class, the href and the row's own <code>data-kind</code> / <code>data-active</code> / <code>aria-current</code> attributes, so the tree keeps ownership of the state and you keep ownership of navigation.</>],["label",`string`,<>Names the navigation landmark. Set it whenever a page carries more than one tree.</>],],notes:[<><strong>It is a nested list of disclosures, not an ARIA tree widget.</strong> Every row is a real button or anchor in the tab order and each folder carries <code>aria-expanded</code> — there is no roving tabstop and no arrow-key navigation. A file browser that needs those is a different component; this is the sidebar shape, and pretending otherwise would ship a <code>role="tree"</code> the keyboard does not honour.</>,<><strong>It reads no filesystem.</strong> You pass <code>nodes</code>, already sorted, already filtered. The tree renders them in the order given.</>,<><strong>A closed folder is hidden with <code>hidden</code>, not with a stylesheet</strong> — so its rows are out of the accessibility tree and out of in-page search, rather than being findable text the reader cannot see.</>,<>Rows press rather than tint. The design system's own tree washed a hovered row in 6% ink and the active row in 12% brand; a row being pointed at is not a category, so both are depth here and papaya arrives as ink.</>,<>The chevron carries no glow. It turns and steps its ink — a glow is how this system reports state, and the state is already in the depth under it.</>,<>When both <code>href</code> and <code>onSelect</code> are given, both fire: the anchor navigates and the callback runs. Prevent the default in your own handler if you are routing yourself, or reach for <code>renderLink</code>.</>,],preview:<FileTree label="Repository" activeId="checkout" defaultOpen={["root","storefront"]} nodes={[{id:"root",name:"commercely",children:[{id:"storefront",name:"storefront",children:[{id:"checkout",name:"checkout.tsx",meta:"TSX"},{id:"cart",name:"cart.ts",meta:"TS"},{id:"theme",name:"theme.css",meta:"CSS"}]},{id:"api",name:"api",children:[{id:"routes",name:"routes.ts",meta:"TS"}]},{id:"pkg",name:"package.json",meta:"JSON"}]},{id:"docs",name:"docs",children:[{id:"runbook",name:"runbook.md",meta:"MD"}]}]}/>},
 {id:"pricing-table",name:"PricingTable",group:"Marketing",summary:"The plan grid: a price, what it includes, and the way to take it. One card per plan, each carrying its own call to action, so the reader decides and acts in the same place. The plan being argued for is reported by depth and papaya ink — never by a fill.",code:`import { PricingTable, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<PricingTable\n  label="Engagement models"\n  plans={[\n    {\n      id: "discovery",\n      name: "Discovery",\n      price: "₹2.4L",\n      period: "/ 2 weeks",\n      features: ["Architecture review", "Engagement plan and estimate"],\n      action: <Button size="lg" style={{ width: "100%" }}>Start discovery</Button>,\n    },\n    {\n      id: "engagement",\n      name: "Engagement",\n      price: "₹8L+",\n      period: "/ month",\n      featured: true,\n      features: ["4-week sprints, weekly demos", "Senior pair, runbook-led"],\n      action: <Button size="lg" style={{ width: "100%" }}>Start engagement</Button>,\n    },\n  ]}\n/>`,options:[["plans[]",`{ id, name, price, period?, description?, features[], action?, featured?, featuredLabel? }`,<><code>price</code> is rendered exactly as given — the component does no currency work, no rounding and no localisation, because a price is copy. <code>period</code> is the mono line beside it: <em>/ month</em>, <em>/ 2 weeks</em>.</>],["featured",`boolean`,<>Marks the plan the page is arguing for. It sits further out of the page than its neighbours and the edge ring it already carries turns papaya. Mark <strong>one</strong>: two featured plans is the same as none.</>],["featuredLabel",`ReactNode · default "Most picked"`,<>What the mark on the featured plan reads. Say why it is picked — “Most picked”, “Best for 20–50 seats” — rather than repeating the plan's name.</>],["action",`ReactNode`,<>The plan's own call to action. You supply the control, so it can be a <code>Button</code>, an anchor, or a form submit. Give it <code>width: 100%</code> if you want it to fill the card.</>],["features[]",`ReactNode[]`,<>What the plan <strong>includes</strong>. Every entry is marked with the same tick a comparison table uses for <em>yes</em>.</>],["min",`number · default 260`,<>Smallest a plan may get before the grid drops a column.</>],["label",`string`,<>Names the group of plans for a screen reader.</>],],notes:[<><strong>This is not <a href="#comparison-table">ComparisonTable</a>, and the two are not interchangeable.</strong> A pricing table is an <em>offer</em> — one card per plan with its own call to action, so the reader chooses and acts in one place. A comparison table is an <em>argument</em> — a matrix of criteria against options, with nothing to act on. A page that needs both uses both: the grid to decide, the matrix to justify. Building this out of a comparison table with a price row leaves you a price in a cell and nothing to press.</>,<><strong>There is no “not included” row.</strong> Every feature listed is an inclusion. A plan that has to say what it leaves out is making a comparison, and that is <code>ComparisonTable</code>'s job — it draws a real cross for <code>false</code>, which a greyed tick never does.</>,<><strong>It does no arithmetic.</strong> No annual/monthly toggle, no seat multiplier, no tax. Pass the numbers you want shown; a calculator is page state and belongs above the component.</>,<>The design system's own card fills its “most picked” mark with papaya and rings the plan in 2px of brand. Neither is reproduced: the mark is a carved chip carrying papaya as ink, and the emphasis is depth.</>,<>The action is pinned to the foot of the card, so a row of plans with different feature counts still lines its buttons up.</>,<>Each plan is an <code>article</code> labelled by its own name, so a screen reader announces the plan before its price rather than reading a loose column of numbers.</>,],preview:<PricingTable label="Engagement models" plans={[{id:"discovery",name:"Discovery",price:"₹2.4L",period:"/ 2 weeks",description:"A scoped fortnight before anyone writes code.",features:["Architecture review","Engagement plan and estimate","No code, no surprises"],action:<Button size="lg" style={{width:"100%"}}>Start discovery</Button>},{id:"engagement",name:"Engagement",price:"₹8L+",period:"/ month",featured:true,description:"The build, run by a senior pair.",features:["4-week sprints, weekly demos","Senior pair, runbook-led","Hetzner, AWS or on-prem","Quarterly tune-ups included"],action:<Button size="lg" style={{width:"100%"}}>Start engagement</Button>},{id:"managed",name:"Managed",price:"₹2.4L+",period:"/ month",description:"After go-live, for as long as you want us.",features:["24×7 on-call rotation","Dependency and architecture care","4-hour response SLA"],action:<Button size="lg" variant="outline" style={{width:"100%"}}>Talk to managed</Button>}]}/>},
 {id:"code-block",name:"CodeBlock",group:"Surfaces & data",summary:"Code, housed. A Frame with the slots a listing needs already wired — the language and the file above, a CopyChip in the corner, the source in the well. It does no syntax highlighting: you pass pre-highlighted markup and it draws the box.",code:`import { CodeBlock } from "@mithtech-bengaluru/tonaldepth-react";\n\nconst SOURCE = \`export default defineEventHandler(async event => {\n  const id = getRouterParam(event, "id");\n  return db.engagements.find({ id });\n});\`;\n\n{/* Plain text — no highlighter involved. */}\n<CodeBlock language="TypeScript" title="server/api/[id].ts" code={SOURCE} />\n\n{/* Pre-highlighted: the markup is yours, the four token classes are ours. */}\n<CodeBlock language="TypeScript" code={SOURCE}>\n  <span className="td-cb-k">const</span> id = <span className="td-cb-n">getRouterParam</span>(event, <span className="td-cb-s">"id"</span>);\n</CodeBlock>`,options:[["code",`string`,<><strong>Required.</strong> The raw source. It is what the copy control puts on the clipboard, and what is rendered when no <code>children</code> are passed. Keep it in sync with the markup — nothing checks that they agree.</>],["children",`ReactNode`,<>Pre-highlighted markup. Replaces the plain text on screen; <code>code</code> is still what gets copied.</>],["language",`ReactNode`,<>The language tag above the well. A tag, not a sentence — “TypeScript”, “bash”, “JSON”.</>],["title",`ReactNode`,<>What the block is: a route, a path, a filename.</>],["footnote",`ReactNode`,<>A line under the well — where the source came from, what it assumes, which version it is from.</>],["copy",`boolean · default true`,<>The copy chip in the corner. Turn it off for a listing nobody would run — an error message, a diff.</>],["copyLabel / copiedLabel",`string · default "Copy" / "Copied"`,<>The chip's visible text before and while the copied state holds.</>],["copyAriaLabel",`string · default "Copy code"`,<>The chip's accessible name. It has its own prop because the value is a whole file, and a screen reader reading the listing aloud as a button name is not a name.</>],["wrap",`boolean · default false`,<>Wrap long lines instead of scrolling them. Off is right for code, where a wrapped line changes what the code appears to say; on is right for a shell transcript or a log.</>],],notes:[<><strong>It does no syntax highlighting, and it never will.</strong> A highlighter is a grammar per language and a theme per grammar — a dependency the size of this library behind a component that draws a box. Bring your own (Shiki, Prism, highlight.js, a server route) and pass the markup as <code>children</code>. Four token classes are styled for you: <code>td-cb-k</code> keyword, <code>td-cb-s</code> string, <code>td-cb-n</code> name, <code>td-cb-c</code> comment. Anything else you class yourself.</>,<><strong>The well is the surface pressed in, not a dark slab.</strong> The design system's own panel hardcodes <code>#1A1815</code> and <code>#F0EDE5</code> in both themes. A well is the plain material carved inward, and a fixed dark ground on a paper page is a tinted band — so the recess carries the separation and the token colours follow the theme.</>,<><strong>No line numbers, no diff gutter, no line highlighting.</strong> Each of those is a second column of markup the caller would have to produce anyway; when you need them, put them in the highlighted markup you are already passing.</>,<>The listing is its own scroller and is focusable, so a line wider than the page can be reached from the keyboard rather than only by dragging.</>,<><code>code</code> is what is copied even when <code>children</code> are given. If the two disagree the reader copies <code>code</code> — which is the right way round, because that is the text that runs.</>,<>The whole thing is a <code>figure</code>, so the listing and its caption are announced as one object rather than a heading followed by loose text.</>,],preview:<div style={{display:"grid",gap:20}}><CodeBlock language="TypeScript" title="server/api/engagements/[id].ts" code={'import { defineEventHandler } from "h3";\n\nexport default defineEventHandler(async event => {\n  const id = getRouterParam(event, "id");\n  return db.engagements.find({ id });\n});'} footnote="Nuxt 4 · h3 route handler"><span className="td-cb-c">{"// discovery route"}</span>{"\n"}<span className="td-cb-k">import</span>{" { "}<span className="td-cb-n">defineEventHandler</span>{" } "}<span className="td-cb-k">from</span> <span className="td-cb-s">{"\"h3\""}</span>{";\n\n"}<span className="td-cb-k">export default</span> <span className="td-cb-n">defineEventHandler</span>{"("}<span className="td-cb-k">async</span>{" event => {\n  "}<span className="td-cb-k">const</span>{" id = "}<span className="td-cb-n">getRouterParam</span>{"(event, "}<span className="td-cb-s">{"\"id\""}</span>{");\n  "}<span className="td-cb-k">return</span>{" db.engagements.find({ id });\n});"}</CodeBlock><CodeBlock language="bash" copy={false} wrap code={"pnpm add @mithtech-bengaluru/tonaldepth-react --registry https://npm.po5.in"}/></div>},
 {id:"breadcrumbs",name:"Breadcrumbs",group:"Navigation",summary:"Where this page sits, and the way back up. Three forms on one prop — chevrons, slashes, and the condensed bar that houses them. The last crumb is the page you are on, so it is not a link.",code:`import { Breadcrumbs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<Breadcrumbs\n  items={[\n    { label: "mith.tech", href: "/" },\n    { label: "Work", href: "/work" },\n    { label: "2026", href: "/work/2026" },\n    { label: "Commercely replatform" },\n  ]}\n/>\n\n{/* The condensed form: chevrons inside a housed bar, for a dense header. */}\n<Breadcrumbs separator="condensed" items={items} />`,options:[["separator",`"chevron" · default`,<>A single right-angle mark between crumbs. The default, and the one for an application header.</>],["separator",`"slash"`,<>A forward slash. Reads as a path, which is what you want when the trail <em>is</em> a path — a docs tree, a file browser, a URL.</>],["separator",`"condensed"`,<>Chevrons inside a housed bar. The trail becomes one raised object that scrolls sideways rather than wrapping, for a header with no room to give it two lines.</>],["items[]",`{ label, href? }`,<>In order, root first. A crumb with no <code>href</code> renders as plain text — useful for a level that exists in the hierarchy but has no page of its own.</>],["label",`string · default "Breadcrumb"`,<>Names the navigation landmark. Change it when a page has more than one trail.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href and the children, return the element. The last crumb never reaches it.</>],],notes:[<><strong>The last crumb is never a link, and its <code>href</code> is ignored.</strong> It is the page the reader is already on: a link to where you already are is not a destination, and it would make the crumb's press read as a control that does nothing. It carries <code>aria-current="page"</code> instead, which is what a screen reader announces.</>,<><strong>Three forms, one prop, no cross product.</strong> <code>condensed</code> is a value of <code>separator</code> rather than a second <code>housed</code> boolean, because the design system draws exactly these three — and a separator-times-housing prop pair would let you build a slash-in-a-bar nobody has drawn.</>,<><strong>It does not truncate.</strong> A trail too long for its line wraps, and the condensed form scrolls inside its own bar. Collapsing the middle behind an ellipsis loses the one thing a breadcrumb is for; shorten the labels instead, or pass fewer crumbs.</>,<>Crumbs that lead somewhere press — hover sinks them, the press sinks them deeper. The current crumb does not press at all, because it is not a control.</>,<>The separator is drawn in CSS as punctuation, not as an icon. It sits between two words and means nothing on its own, so it is never a lamp and never carries a glow.</>,<>It renders a real <code>nav &gt; ol</code>, so the order is announced as an ordered list rather than as a row of loose links.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><Breadcrumbs items={[{label:"Dashboard",href:"#breadcrumbs"},{label:"Engagements",href:"#breadcrumbs"},{label:"Commercely",href:"#breadcrumbs"},{label:"Build sprint 4"}]}/><Breadcrumbs separator="slash" items={[{label:"mith.tech",href:"#breadcrumbs"},{label:"Work",href:"#breadcrumbs"},{label:"2026",href:"#breadcrumbs"},{label:"Commercely"}]}/><Breadcrumbs separator="condensed" items={[{label:"Work",href:"#breadcrumbs"},{label:"SaaS",href:"#breadcrumbs"},{label:"Commercely replatform"}]}/></div>},
 {id:"pagination",name:"Pagination",group:"Navigation",summary:"The page trail, cut where it has to be. The page you are on is not a target — it rests recessed with papaya ink rather than being filled with the brand colour, because a button that reloads where you already are is a control that appears to do nothing.",code:`import { Pagination } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* Button mode — you own the state. */}\n<Pagination page={page} pageCount={42} onPageChange={setPage} />\n\n{/* Link mode — real hrefs, which is what a crawler and a middle-click need. */}\n<Pagination\n  page={page}\n  pageCount={42}\n  href={n => \`/blog/page/\${n}\`}\n  renderLink={({ className, href, children, ...rest }) => (\n    <Link className={className} href={href} {...rest}>{children}</Link>\n  )}\n/>`,options:[["page / pageCount",`number`,<>Both 1-based. <code>page</code> is the page being read; the component derives everything else from the pair.</>],["onPageChange",`(page: number) => void`,<>Fires with the page that was chosen. Ignored in link mode — there the anchor navigates.</>],["siblings",`number · default 1`,<>How many pages stay visible either side of the current one before the trail is cut.</>],["boundaries",`number · default 1`,<>How many pages stay visible at each end. Raise it when the last page number is itself information — a 214-page archive says something the ellipsis does not.</>],["href",`(page: number) => string`,<>Give it a builder and every target renders as a real anchor instead of a button. That is the right mode for anything a crawler reads or a reader middle-clicks.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href, the children and the accessible name, return the element. Only used alongside <code>href</code>.</>],["label / previousLabel / nextLabel",`string`,<>Names for the landmark and the two edge controls. Translate them with the rest of the page.</>],["pageLabel",`(page: number) => string · default "Page {n}"`,<>The accessible name of a numbered target. The visible text is the bare number, which on its own is not a name.</>],],notes:[<><strong>The current page is not a target.</strong> It renders as plain text with <code>aria-current="page"</code> and rests recessed. A button that reloads where you already are appears to do nothing, and the recess is already how this system says “this one is selected”.</>,<><strong>It holds no state.</strong> You pass <code>page</code> and you move it — from your own state in button mode, or from the route in link mode. Owning the page number here would fight every router that already owns it.</>,<><strong>It does not know how many rows there are.</strong> Pass <code>pageCount</code>; deriving it from a total and a page size is arithmetic the caller already did to fetch the rows.</>,<><strong>A cut is only drawn where it saves more than one number.</strong> Replacing a single hidden page with an ellipsis costs the same width and takes away a target, so the trail shows that page instead.</>,<>The edge controls stay drawn when they are out of reach — disabled rather than removed — so the row does not change width as the reader walks it. They carry <code>aria-disabled</code> and never fire.</>,<>Every target presses; none of them tints. The previous and next marks are direction marks and carry no glow.</>,],preview:<div style={{display:"grid",gap:20,justifyItems:"start"}}><Pagination page={1} pageCount={4}/><Pagination page={8} pageCount={42}/><Pagination page={42} pageCount={42} boundaries={2}/></div>},
 {id:"map",name:"Map",group:"Surfaces & data",summary:"A static locator. No tile provider and no network call — a carved ground, an optional graticule, and pins placed at percentages you give it. Bring your own outline; the component positions the lamps over it.",code:`import { Map } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* \`Map\` shadows the global. Alias it wherever you also use the built-in. */}\nimport { Map as LocatorMap } from "@mithtech-bengaluru/tonaldepth-react";\n\n<LocatorMap\n  label="Where we work"\n  pins={[\n    { id: "blr", label: "Bengaluru", x: 34, y: 72 },\n    { id: "bom", label: "Mumbai", x: 22, y: 58, tone: "accent" },\n    { id: "del", label: "Delhi", x: 33, y: 28, tone: "accent" },\n  ]}\n>\n  <svg viewBox="0 0 100 100" aria-hidden="true">{/* your outline */}</svg>\n</LocatorMap>`,options:[["pins[]",`{ id, label, x, y, tone?, description? }`,<><code>x</code> and <code>y</code> are percentages of the box measured from its top left, <strong>not</strong> latitude and longitude. <code>description</code> is read after the label where the name alone does not say enough.</>],["pins[].tone",`"brand" · default`,<>The papaya lamp. Where every pin means the same thing, leave them all on it — colour is category, and one category is no colour at all.</>],["pins[].tone",`"accent" | "green" | "error" | "neutral"`,<>The other categories: azure, green, red, and an unlit grey for a location that is only context. Reach for these when the pins genuinely differ in kind — offices against sites, live against planned.</>],["label",`string`,<><strong>Required.</strong> The map's accessible name. It has no other one, because the ground is decorative and the pins are just text.</>],["children",`ReactNode`,<>The ground: your own outline, as inline SVG or an image. It is rendered <code>aria-hidden</code> and stretched to the box.</>],["grid",`boolean · default true`,<>The graticule under the ground. Ink at low alpha — it is a ruler, not a signal.</>],["ratio",`number · default 16 / 9`,<>Width over height. The map takes its container's width and derives its height from this.</>],["showLabels",`boolean · default true`,<>Off leaves the lamps on the map and keeps every name readable to a screen reader. For a dense map where the labels would collide.</>],],notes:[<><strong>No tile provider, no network call, and no key.</strong> Reaching a tile server would put a third party in the render path of every page that shows an office address, and it would want a key, a consent banner and an attribution line for a picture that never changes. Pass your own outline instead.</>,<><strong>It does not project coordinates.</strong> <code>x</code> and <code>y</code> are percentages of the box. The outline is yours, so only you know what projection it is in — converting latitude and longitude here would mean guessing at one.</>,<><strong>It is already a well.</strong> A map is a measured object and data is recessed, so it is the surface pressed in rather than a plate. If you need a title, an eyebrow or a source line around it, put it in a <a href="#frame">Frame</a> — the map drops its own recess on the way into the frame's well rather than sitting as a trough inside a trough.</>,<><strong>The export is named <code>Map</code> and shadows the JavaScript built-in.</strong> Alias it on import — <code>import {"{ Map as LocatorMap }"}</code> — in any module that also constructs a <code>new Map()</code>. The registry copy is <code>TonalDepthMap</code> and has no such clash.</>,<>The design system's own map fills its ground with an accent-to-brand gradient. That is not reproduced: filling with the brand colour is the one move the system forbids, and a tinted plane is not a boundary. The ground is the plain surface carved inward.</>,<>Each pin is a lamp in a socket — the socket is the map's own material and is never tinted, the lens is lit from a named light, and colour exists only where the light is.</>,<>Pins are not interactive. There is no hover card, no click target and no clustering; a map that has to be operated is a different component and wants a real mapping library behind it.</>,],preview:<LocatorMap label="Where we work" pins={[{id:"blr",label:"Bengaluru",x:32,y:74},{id:"bom",label:"Mumbai",x:20,y:60,tone:"accent"},{id:"del",label:"Delhi",x:31,y:26,tone:"accent"},{id:"maa",label:"Chennai",x:40,y:84,tone:"neutral"}]}/>},
 {id:"profile-card",name:"ProfileCard",group:"Marketing",summary:"A person: the mark, the name, the role, and what they own. One card covers the profile card and the team wall — the same parts in a different reading order, so they are two layouts rather than two components.",code:`import { ProfileCard, IconButton } from "@mithtech-bengaluru/tonaldepth-react";\n\n{/* The byline form: the mark beside the name. */}\n<ProfileCard name="Manoj M" role="Principal · Engagements" initials="MM" href="/about/manoj" />\n\n{/* The team wall: the mark above the name, with a bio and controls. */}\n<ProfileCard\n  layout="stack"\n  name="Manoj M"\n  role="Principal · Engagements"\n  initials="MM"\n  actions={<IconButton tone="papaya" icon={<EmailIcon />} label="Email Manoj" />}\n>\n  Owns the engagement model, the runbook template and the Friday status email.\n</ProfileCard>`,options:[["layout",`"row" · default`,<><code>05-cards/profile</code>: the mark beside the name. For a byline, an owner, a contact — anywhere a person is a fact about something else.</>],["layout",`"stack"`,<><code>10-marketing/team</code>: the mark above the name, with room for a bio under it. For a wall of people, where the person <em>is</em> the content.</>],["initials",`string`,<>Two letters, when there is no photograph. Set in the display face inside a carved disc.</>],["avatar",`ReactNode`,<>A photograph or a drawn mark. <strong>It wins over <code>initials</code></strong>, and it is cropped to the disc — pass a square image or expect the sides to go.</>],["role",`ReactNode`,<>The line under the name, in mono small caps. The role, not a sentence.</>],["children",`ReactNode`,<>The bio. Capped at 46 characters a line, because it is prose and prose has a measure.</>],["actions",`ReactNode`,<>Controls at the foot of the card — an <a href="#icon-button">IconButton</a> per channel, a <a href="#button">Button</a>. You supply them, so they are real components rather than a link shape invented here.</>],["href",`string`,<>Makes the name a link — and the whole card a target when there are no <code>actions</code>.</>],["renderLink",`(props) => ReactNode`,<>Hand your router the anchor. Given the class, the href and the children, return the element.</>],],notes:[<><strong>One card for two design pages, on purpose.</strong> <code>05-cards/profile</code> and <code>10-marketing/team</code> are the same parts — mark, name, role, bio, controls — in a different reading order. Two components would have meant correcting the avatar, the role line and the depth ladder twice, in step, forever.</>,<><strong><code>href</code> and <code>actions</code> disagree, and <code>actions</code> wins.</strong> The whole card is a target only when it carries none: a full-card overlay on top of an email button is an overlay that eats the button. With actions present, <code>href</code> links the name alone.</>,<><strong>The team card's gradient avatar is not reproduced.</strong> The design system fills it brand-to-accent with white initials; filling with the brand colour is the one move the system forbids, so the mark is a disc carved from the surface with the initials in the display face.</>,<><strong>Nor is its papaya role line.</strong> A role is not a category, and a wall of eight people would put papaya on all eight — spending the one signal the system reserves for meaning. The role is ink.</>,<>It renders an <code>article</code> labelled by the name, so a screen reader announces who this is before reading the role.</>,<>There is no social-link row of its own. Channel controls are <code>IconButton</code>s in <code>actions</code>, which is how every other channel in the system is drawn — icon as the lamp, label as its accessible name.</>,],preview:<div style={{display:"grid",gap:20}}><ProfileCard name="Manoj M" role="Principal · Engagements" initials="MM" href="#profile-card"/><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:20}}><ProfileCard layout="stack" name="Manoj M" role="Principal · Engagements" initials="MM" actions={<IconButton tone="papaya" icon={<EmailIcon weight={LAMP_WEIGHT}/>} label="Email Manoj" href="#profile-card"/>}>Owns the engagement model, the runbook template and the Friday status email.</ProfileCard><ProfileCard layout="stack" name="Rohan Iyer" role="Lead · Platform" initials="RI" actions={<IconButton tone="azure" icon={<LinkedInIcon weight={LAMP_WEIGHT}/>} label="Rohan on LinkedIn" href="#profile-card"/>}>Runs the Hetzner estate, the backup drills and the on-call rotation.</ProfileCard></div></div>},
 {id:"mega-cascade",name:"MegaCascade",group:"Mega menus",summary:"The three-level panel: categories, subcategories, items. Each column is a well, both rails are roving-tabindex tablists, and selection deliberately never resets on mouse-out — snapping back while the pointer travels toward the next column is the classic mega-menu bug.",code:`import { MegaCascade } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaCascade\n  renderLink={({ className, href, children }) => (\n    <Link className={className} href={href}>{children}</Link>\n  )}\n  groups={[\n    {\n      id: "run",\n      label: "What we run",\n      branches: [\n        {\n          id: "erp",\n          title: "ERP",\n          hint: "Process, hosting, tuning",\n          href: "/services/erp",\n          items: [{ href: "/services/erpnext", title: "ERPNext implementation", detail: "9 pages" }],\n        },\n      ],\n    },\n  ]}\n/>`,options:[["groups[]",`{ id, label, icon?, count?, branches[] }`,<>Column one. <code>count</code> defaults to the sum of the branches’ items; pass <code>null</code> to show no number at all.</>],["groups[].branches[]",`{ id, title, hint?, href?, count?, items[] }`,<>Column two. <code>hint</code> is the line under the title — what this slice is <em>for</em>. <code>href</code> makes the branch itself navigable and adds a “See all” under its items.</>],["branches[].items[]",`{ href, title, detail? }`,<>Column three, the leaves. <code>detail</code> is the dimmer half after the title: the platform, the format, the year.</>],["renderLink",`(props) => ReactNode`,<>Hand your router every anchor in column three. Without it they are plain anchors, which in a SPA is a full document load out of an open menu.</>],["categoriesLabel",`string · default "Categories"`,<>Names the first rail for a screen reader. The second names itself from the chosen category.</>],],notes:[<><strong>Three levels, not two, and that is a sizing decision.</strong> Two puts the whole leaf set in column two, so the panel is sized by the biggest category — fourteen topics in one column with no room to say anything about any of them. The third level lets a category be deep without being tall.</>,<><strong>Column one is click-only; column two follows the pointer.</strong> Hovering across five rows on the way to column two would otherwise change the selection on every row the pointer crosses, and the sheet reads as resizing even though its frame never moves. There is no journey to protect inside column two, so it switches at once — a delay on an already-open sheet reads as lag.</>,<><strong>Selection never resets on mouse-out.</strong> Snapping back to the first category while the pointer travels toward the next column is the classic mega-menu bug, and three columns make that journey longer.</>,<><strong>Every column is a well.</strong> Chrome is raised and the things you are choosing between are recessed, so the sheet reads as a housing with contents rather than three floating lists.</>,<>Both rails are roving-tabindex tablists: up and down move within a rail, right steps into the next, left steps back, Home and End jump to the ends, and Tab leaves for the item links.</>,<>It renders the panel body only. The sheet, its head, its close control and its footer belong to <a href="#site-navigation">SiteNavigation</a>; this goes in a menu item’s <code>content</code>.</>,],preview:<div className="mega-stage"><MegaCascade groups={[{id:"run",label:"What we run",icon:<ICube/>,branches:[{id:"erp",title:"ERP",hint:"Process, hosting, tuning",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"ERPNext implementation",detail:"9 pages"},{href:"#mega-cascade",title:"Data migration",detail:"Tally, SAP, sheets"},{href:"#mega-cascade",title:"Module customisation"},{href:"#mega-cascade",title:"Upgrades and tune-ups"}]},{id:"commerce",title:"Commerce",hint:"Storefront, checkout, catalogue",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"Medusa storefronts",detail:"Headless"},{href:"#mega-cascade",title:"Payments",detail:"Stripe, Razorpay"},{href:"#mega-cascade",title:"Shopify migration"}]},{id:"automation",title:"Automation",hint:"The wiring between systems",items:[{href:"#mega-cascade",title:"n8n workflows"},{href:"#mega-cascade",title:"Event pipelines"},{href:"#mega-cascade",title:"Custom integrations"}]}]},{id:"know",label:"Knowledge",icon:<IList/>,branches:[{id:"guides",title:"Guides",hint:"Long-form, start to finish",href:"#mega-cascade",items:[{href:"#mega-cascade",title:"ERPNext in 90 days"},{href:"#mega-cascade",title:"Choosing a gateway"},{href:"#mega-cascade",title:"Self-hosting on Hetzner"}]},{id:"comparisons",title:"Comparisons",hint:"One against another, with numbers",count:46,items:[{href:"#mega-cascade",title:"ERPNext vs SAP B1"},{href:"#mega-cascade",title:"Medusa vs Shopify"},{href:"#mega-cascade",title:"Plane vs Jira"}]},{id:"studies",title:"Case studies",hint:"What shipped, and what it cost",items:[{href:"#mega-cascade",title:"Commercely replatform",detail:"Retail"},{href:"#mega-cascade",title:"Rework Industries",detail:"Manufacturing"}]}]},{id:"company",label:"Company",icon:<IGear/>,branches:[{id:"about",title:"About",hint:"Who is actually doing the work",items:[{href:"#mega-cascade",title:"How we work"},{href:"#mega-cascade",title:"The team"},{href:"#mega-cascade",title:"Careers",detail:"3 open"}]}]}]}/></div>},
 {id:"mega-tabs",name:"MegaTabs",group:"Mega menus",summary:"The two-column panel: a rail of options on the left, one pane on the right. Reach for it when each option deserves a paragraph — what it includes, what it costs, where to read more.",code:`import { MegaTabs } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaTabs\n  label="Services"\n  items={[\n    {\n      id: "erpnext",\n      label: "ERPNext operations",\n      hint: "Process design, hosting and tuning",\n      panel: <ServicePane />,\n    },\n  ]}\n/>`,options:[["items[]",`{ id, label, hint?, icon?, panel }`,<><code>hint</code> is the second line in the rail — what the option is, in a few words. <code>panel</code> is what it is worth saying at length.</>],["value / defaultValue / onValueChange",`string`,<>Control the open option, or leave it uncontrolled. With neither, the first item opens.</>],["label",`string · default "Options"`,<>Names the rail for a screen reader.</>],],notes:[<><strong>The pane changes on click, never on hover.</strong> It followed the pointer at first, on the reasoning that one rail has no journey to protect. That is wrong for a different reason: the pane is the panel’s whole right-hand side, so a pointer crossing the rail on its way anywhere repaints most of the sheet. A rail that swaps a paragraph under the pointer reads as the menu being unstable, not as it being responsive.</>,<><strong>Choose between the two by what an option is worth.</strong> If each one deserves a paragraph, this. If the options are themselves categories with depth under them, the cascade — putting depth in a pane makes the pane the panel’s height.</>,<>The rail is a real tablist: up and down move, Home and End jump to the ends, and the pane is the tabpanel the selected tab controls.</>,<>Both columns are wells, and the option rows take the system’s row ladder — hover sinks, the press sinks deeper, and the chosen row rests recessed.</>,],preview:<div className="mega-stage"><MegaTabs label="Services" items={[{id:"erpnext",label:"ERPNext operations",hint:"Process design, hosting and tuning",icon:<ICube/>,panel:<><h4 style={{margin:0}}>ERPNext operations</h4><p className="sub" style={{margin:0}}>We pick the modules, design the workflows and own the infrastructure — your team runs the day to day.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Process design and module customisation</a></li><li><a href="#mega-tabs">Self-hosting on Hetzner, AWS or on-prem</a></li><li><a href="#mega-tabs">Monthly tune-ups and quarterly upgrades</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>},{id:"medusa",label:"Medusa commerce",hint:"Headless storefronts, not Shopify",icon:<IGrid/>,panel:<><h4 style={{margin:0}}>Medusa commerce</h4><p className="sub" style={{margin:0}}>Storefront, checkout and the ERP bridge — and the catalogue migrated without taking the shop down.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Storefront and checkout on Medusa</a></li><li><a href="#mega-tabs">Stripe, Razorpay or your own gateway</a></li><li><a href="#mega-tabs">Inventory and ERP sync</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>},{id:"plane",label:"Plane workflows",hint:"Execution without the SaaS bill",icon:<IList/>,panel:<><h4 style={{margin:0}}>Plane workflows</h4><p className="sub" style={{margin:0}}>Issues, cycles and modules, self-hosted, without Atlassian per-seat pricing.</p><ul className="td-react-mega-items"><li><a href="#mega-tabs">Self-hosted Plane and custom modules</a></li><li><a href="#mega-tabs">GitHub and GitLab sync</a></li></ul><a className="td-mega-cta" href="#mega-tabs">Engagement model</a></>}]}/></div>},
 {id:"mega-grid",name:"MegaGrid",group:"Mega menus",summary:"Cards in a well — the simplest panel, and the one most likely to be got wrong. A grid of cards sitting directly on the sheet has the cards and their housing at the same depth, so nothing reads as contained. MegaActions is the footer rail that goes with it.",code:`import { MegaGrid, MegaActions, FeatureCard, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaGrid min={220}>\n  <FeatureCard tone="brand" title="ERPNext" href="/services/erpnext">\n    The full rollout.\n  </FeatureCard>\n</MegaGrid>\n\n{/* In the panel footer slot, not in a column. */}\n<MegaActions>\n  <a className="td-cta" href="/pricing">Pricing</a>\n  <Button variant="primary" size="sm">Talk to us</Button>\n</MegaActions>`,options:[["min",`number · default 220`,<>Smallest a card may get before the grid drops a column.</>],["children",`ReactNode`,<>The cards. <a href="#feature-card">FeatureCard</a> is the shape this was drawn for; anything else that is a card works the same.</>],],notes:[<><strong>Give every card an <code>href</code>.</strong> A card in a menu that cannot be clicked is a picture of a menu — and with one it takes the whole-card link ladder, so it lifts on hover and presses under the pointer like everything else in the system.</>,<><strong>It is a well, not a grid.</strong> That is the whole component: <code>display: grid</code> on the panel body is two lines anyone would write, and it produces cards floating on their own housing at the same depth. Chrome is raised, what you are choosing between is recessed.</>,<><strong><code>MegaActions</code> belongs in the panel footer, not in a column.</strong> In a column it spends a third of the sheet on links that never change and scrolls away with the content; in the footer it sits outside the scroll area and stays reachable however far a column grows.</>,<>Use it when the options need no explaining beyond a line each. When they do, reach for <a href="#mega-tabs">MegaTabs</a>; when they have depth under them, <a href="#mega-cascade">MegaCascade</a>.</>,],preview:<div className="mega-stage"><MegaGrid><FeatureCard tone="brand" icon={ICON_DEMO} title="ERPNext" href="#mega-grid" points={["Discovery to go-live"]}>The full rollout, run by the people who stay.</FeatureCard><FeatureCard tone="accent" icon={ICON_DEMO} title="Medusa" href="#mega-grid" points={["Headless catalogue"]}>Commerce, front and back.</FeatureCard><FeatureCard tone="green" icon={ICON_DEMO} title="n8n" href="#mega-grid" points={["Event-driven flows"]}>The wiring between the systems.</FeatureCard><FeatureCard tone="brand" icon={ICON_DEMO} title="Plane" href="#mega-grid" points={["GitHub sync"]}>Execution without the SaaS bill.</FeatureCard></MegaGrid><MegaActions style={{marginTop:16}}><a className="td-cta" href="#mega-grid">Pricing</a><Button variant="primary" size="sm">Talk to us</Button></MegaActions></div>},
 {id:"mega-columns",name:"MegaColumns",group:"Mega menus",summary:"The widest panel, and the one for a menu that has to teach as well as navigate: a feature that makes the case beside titled columns of destinations, with a rail across the foot. Cascade is for depth, tabs are for options that need a paragraph — this is for breadth.",code:`import { MegaColumns, MegaFeature, Button } from "@mithtech-bengaluru/tonaldepth-react";\n\n<MegaColumns\n  feature={\n    <MegaFeature\n      eyebrow="New to open source ERP?"\n      title="Start with the basics"\n      steps={["Read how it runs", "Book a call", "Agree the scope", "Go live"]}\n      action={<Button variant="primary" size="sm">Open the learn hub</Button>}\n    >\n      A plain-English walkthrough of how a rollout actually works.\n    </MegaFeature>\n  }\n  sections={[\n    {\n      id: "read",\n      label: "Read & learn",\n      links: [{ href: "/learn", title: "Learn hub", detail: "Every guide, by topic" }],\n    },\n  ]}\n  footer={<Button variant="primary" size="sm">Create a free account</Button>}\n/>`,options:[["sections[]",`{ id, label, links[] }`,<>One titled column each. <code>label</code> is a category in small caps, not a sentence — it is marked with a short papaya rule rather than a line across the column, because a full-width rule is a divider and this is a label.</>],["sections[].links[]",`{ href, title, detail?, icon? }`,<><code>detail</code> is what the reader gets for the click, and it is the difference between a menu and a list of nouns. <code>icon</code> takes a filled glyph in its own tile.</>],["feature",`ReactNode`,<>The panel argument, in a fixed first track. A <a href="#mega-columns">MegaFeature</a>, or anything else that earns the width. Omit it and the sections take the whole sheet.</>],["footer",`ReactNode`,<>A rail across the foot, outside the columns\u2019 scroll: app badges, a standing offer, the last link.</>],["renderLink",`(props) => ReactNode`,<>Hand your router every destination in the columns.</>],["MegaFeature",`{ eyebrow?, title, icon?, children, steps?, action? }`,<><code>steps</code> is a numbered sequence on a rail, for the “here is how this works” a menu sometimes has to carry before anything else makes sense. <code>action</code> is <strong>one</strong> control \u2014 a panel with two calls to action has none.</>],],notes:[<><strong>Three panels, three jobs.</strong> <a href="#mega-cascade">MegaCascade</a> is for depth, <a href="#mega-tabs">MegaTabs</a> is for options that each need a paragraph, and this is for <em>breadth</em>: destinations a reader scans rather than drills into, with one panel making the case for the section as a whole.</>,<><strong>The feature panel is not a coloured card.</strong> The shape it is drawn from fills the panel with a brand colour and sets white on it. Filling with the brand colour is the one move this system forbids, so it is a well instead \u2014 the argument is content, and content is recessed \u2014 with papaya arriving as <em>ink</em> on the eyebrow and the step numbers, which is where the emphasis was doing real work in the original.</>,<><strong>The steps are lamps in sockets on a rail</strong>, which is <a href="#timeline">Timeline</a>\u2019s anatomy. A numbered sequence and a phase sequence are the same object read at two scales, so they are drawn the same way rather than invented twice.</>,<>Every column is a well and scrolls itself, so a column with fourteen links does not make the sheet taller. The panel stays one fixed size whatever is in it.</>,<>The footer sits outside the columns\u2019 scroll, so it stays reachable however far a column grows \u2014 the same reason <a href="#mega-grid">MegaActions</a> belongs in the panel footer rather than in a column.</>,],preview:<div className="mega-stage mega-stage--wide"><MegaColumns feature={<MegaFeature icon={<ICube/>} eyebrow="New to open source ERP?" title="Start with the basics" steps={["Read how an implementation actually runs","Book a discovery call \u2014 about 30 minutes","Agree the scope and the fixed price","Go live, then hand over the runbook"]} action={<Button variant="primary" size="sm">Open the learn hub</Button>}>A plain-English walkthrough of how a self-hosted rollout actually works, and what it costs.</MegaFeature>} sections={[{id:"read",label:"Read & learn",links:[{href:"#mega-columns",title:"Learn hub",detail:"Every guide and article, by topic",icon:<ICube/>},{href:"#mega-columns",title:"News & updates",detail:"What changed this week",icon:<IList/>},{href:"#mega-columns",title:"How it works",detail:"7 steps, signup to go-live",icon:<IGrid/>},{href:"#mega-columns",title:"Glossary",detail:"The terms, explained plainly",icon:<IList/>},{href:"#mega-columns",title:"Release tracker",detail:"Shipped and shipping",icon:<IBell/>}]},{id:"tools",label:"Tools & pricing",links:[{href:"#mega-columns",title:"Calculators",detail:"Cost, sizing and 20 more",icon:<IGrid/>},{href:"#mega-columns",title:"Tools hub",detail:"Calculators, lookups, converters",icon:<ICube/>},{href:"#mega-columns",title:"Migration guide",detail:"Tally, SAP and spreadsheets",icon:<IList/>},{href:"#mega-columns",title:"Pricing methodology",detail:"How we scope and quote",icon:<IGear/>},{href:"#mega-columns",title:"Our fees",detail:"Fixed scope, no hidden hours",icon:<IGrid/>}]}]} footer={<><span className="sub" style={{margin:0,fontFamily:"var(--td-font-mono)",fontSize:"0.62rem",letterSpacing:"0.16em",textTransform:"uppercase"}}>Get the app</span><div style={{display:"flex",gap:10,flexWrap:"wrap"}}><a className="td-cta" href="#mega-columns">App Store</a><a className="td-cta" href="#mega-columns">Google Play</a><Button variant="primary" size="sm">Create a free account</Button></div></>}/></div>},
];
/* The logo bench.

   A logo wall is the one component whose whole point is REAL artwork ([[L13]]),
   and the docs previewed it with three typeset shapes — which is the exact
   thing the component exists to argue against. This lets a reader put their own
   marks through it: pick files, or paste a URL.

   NOTHING IS SAVED. The logos live in this component's state and nowhere else —
   no localStorage, no fixture file, nothing written into the library. A picked
   file becomes an object URL, and the URL is revoked when the logo is removed
   or the page is left, so the blob does not leak for the life of the tab. Say
   so in the UI, because a reader who does not know that will not paste their
   client's mark in. */
function LogoBench(){
  const[logos,setLogos]=useState<{id:string;name:string;src:string;blob:boolean}[]>([]);
  const[url,setUrl]=useState("");
  const[scroll,setScroll]=useState(false);
  const fileInput=useRef<HTMLInputElement>(null);
  /* Revoke on unmount. A blob URL is held by the document until it is revoked,
     so leaving the page without this leaks every file the reader tried. */
  useEffect(()=>()=>{logos.forEach(l=>{if(l.blob)URL.revokeObjectURL(l.src)})},[logos]);
  const addFiles=(files:FileList|null)=>{
    if(!files)return;
    setLogos(current=>[...current,...Array.from(files).map((file,i)=>({
      id:`${file.name}-${current.length+i}`,
      name:file.name.replace(/\.[a-z0-9]+$/i,""),
      src:URL.createObjectURL(file),
      blob:true,
    }))]);
    if(fileInput.current)fileInput.current.value="";
  };
  const addUrl=()=>{
    const value=url.trim();
    if(!value)return;
    let name=value;
    try{name=decodeURIComponent(new URL(value,location.href).pathname.split("/").pop()||value).replace(/\.[a-z0-9]+$/i,"")}catch{/* not a URL we can parse — the raw string is a fine name */}
    setLogos(current=>[...current,{id:`${value}-${current.length}`,name:name||"Logo",src:value,blob:false}]);
    setUrl("");
  };
  const remove=(id:string)=>setLogos(current=>{
    const gone=current.find(l=>l.id===id);
    if(gone?.blob)URL.revokeObjectURL(gone.src);
    return current.filter(l=>l.id!==id);
  });
  const items=logos.map(l=>({name:l.name,logo:<img src={l.src} alt=""/>}));
  return <div className="playground">
    <div className="playground-controls">
      <label className="pg-field"><span>Logo URL</span>
        <input value={url} placeholder="https://example.com/logo.svg" onChange={e=>setUrl(e.target.value)}
          onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addUrl()}}}/></label>
      <Button size="sm" variant="primary" onClick={addUrl}>+ Add URL</Button>
      <Button size="sm" variant="outline" onClick={()=>fileInput.current?.click()}>+ Add files</Button>
      <input ref={fileInput} type="file" accept="image/*" multiple hidden onChange={e=>addFiles(e.target.files)}/>
      <label className="pg-check"><input type="checkbox" checked={scroll} onChange={e=>setScroll(e.target.checked)}/>
        <span>scroll</span></label>
      {logos.length>0&&<Button size="sm" variant="ghost" onClick={()=>{logos.forEach(l=>{if(l.blob)URL.revokeObjectURL(l.src)});setLogos([])}}>Clear</Button>}
    </div>
    {logos.length>0&&<div className="playground-tones">
      {logos.map(l=><label className="pg-tone" key={l.id}>
        <span title={l.name}>{l.name}</span>
        <Button size="sm" variant="ghost" onClick={()=>remove(l.id)}>Remove</Button></label>)}
    </div>}
    <div className="preview"><span>Live React component</span>
      {logos.length
        ?<Specimen><LogoStrip scroll={scroll} speed={26} label={null} items={items}/></Specimen>
        :<p className="hint" style={{margin:0}}>Add a logo by URL or from your computer. They are held in this page only \u2014 nothing is uploaded, nothing is saved, and a picked file is released the moment you remove it or leave.</p>}
    </div>
    <p className="hint"><strong>Nothing here is saved.</strong> The marks live in this page\u2019s memory and nowhere else \u2014 no storage, no fixture, nothing written into the library \u2014 so a client\u2019s artwork can be tried here without it ending up in the repository. Hover one: the wall is grey and quiet until you look at a mark, and the one you are looking at comes back to full colour and steps forward.</p>
  </div>;
}

/* A specimen is operated, not followed.

   Previews carry real hrefs — a FileTree row, a LinkCells card, a breadcrumb —
   because a link with no href is not the component being documented. But
   pressing one to see how it behaves navigated away from the docs, which makes
   the interaction untestable: the thing you were judging is gone.

   The default is cancelled on capture, so the anchor does not navigate while
   every handler the component has still runs and every state — hover, press,
   focus — still reads. `auxclick` covers the middle button, which is a
   separate event and would otherwise open a tab. */
function Specimen({children}:{children:ReactNode}){
  const hold=(event:ReactMouseEvent)=>{
    if((event.target as HTMLElement).closest?.("a[href]")) event.preventDefault();
  };
  return <div className="specimen" onClickCapture={hold} onAuxClickCapture={hold}>{children}</div>;
}
function Copy({text}:{text:string}){const[copied,setCopied]=useState(false);async function run(){await navigator.clipboard.writeText(text);setCopied(true);setTimeout(()=>setCopied(false),1400)}return <Button size="sm" variant="outline" onClick={run}>{copied?"Copied":"Copy"}</Button>}
function Code({children,label="tsx"}:{children:string;label?:string}){return <div className="code"><div><span>{label}</span><Copy text={children}/></div><pre><code>{children}</code></pre></div>}
